-- Migration 0108: Campfire Weeks 1 to 6 Phase 2 Content & RPC Upgrades (Gold Standard Sync)
-- Generated by scripts/gen-campfire-sql.ts from src/data/campfireDaysData.ts, src/data/fanOutLeads.ts,
-- src/data/fragmentMeaningQuestions.ts, src/data/weekQuestions.ts, and src/data/chapterScripts.ts.

-- The Campfire for Week 1, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 1, 1, '{"place":"The forest road","narrated":true,"tone":"wry","cupNight":false,"opener":"One list, one inn''s name. Nothing was taken.","questionTitle":"Were you meant to have the list?","forkA":"He was sent to put it in your hands.","forkB":"You took it off a man carrying it somewhere else.","callback":null,"nudge":"A man who takes nothing, and leaves a list. Who would want you to have it?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"1-1-1","place":"the list, by the last light","actions":[{"attr":"Intellect","verb":"read it again, line by line"},{"attr":"Craft","verb":"hold it to the light and look at the ink"}],"clueTitle":"The even hand","clueText":"Not one name is crossed out or written over. Every line sits level, and the inn''s line is in the same hand as the names.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-1-2","place":"his trail, into the trees","actions":[{"attr":"Aim","verb":"look at his stride"},{"attr":"Agility","verb":"follow where he broke through"}],"clueTitle":"No hurry","clueText":"Twenty paces in, his trail slows to a walk and stays one. He was not running from you. He had finished.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-1-3","place":"the bottom of the cargo box","actions":[{"attr":"Craft","verb":"take the box apart, board by board"},{"attr":"Intellect","verb":"go through it a third time"}],"clueTitle":"The oilcloth","clueText":"Under your things lies a square of oilcloth you never packed, folded small. Whatever he put in the box, he wrapped it first against the wet.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"One stayed close.\"* Why leave four to wander and keep one behind?","weekQuestion":"Why are our names on that list?","pull":"You sit a while on the stone with the list in one hand and the cold thing in the other. The dark comes down through the trees, and somewhere an owl tries its voice.\n\nA man broke into your box to leave you a list with your name on it.\n\n**One day north: the Hollow Wake Inn. Somebody wants you there.**"}'::jsonb),
('dark-moon', 1, 1, 2, '{"place":"The Hollow Wake Inn","narrated":false,"tone":"wry","cupNight":true,"opener":"Four strangers, four torn pages, and an empty chair upstairs. Pull up to the hearth.","questionTitle":"The child in Meira''s notes: when was that child taken?","forkA":"Lately. Whatever was happening there is happening now.","forkB":"Long ago. She was writing about an older taking.","callback":"She hasn''t sat in that seat for three weeks. Your pages all reached you on the road within the same few days.","nudge":"{friend:Intellect}, the page about the child has no date. What would give it one?","nudgeIfLaid":{"piece":"1-2-3","line":"{friend:Intellect}, that leaf. What does it tell you about when she wrote it?"},"narratedSilence":null,"puzzle":{"q":"Did Meira leave in a hurry?","clickText":"Every slip still sits where she pinned it, and the page about the child is the one her thumb wore soft. A woman packing in fear does not leave her book in order. She did not go in a hurry."},"clicks":[{"a":"1-2-2","b":"1-2-3","text":"Every slip still sits where she pinned it, and the page about the child is the one her thumb wore soft. A woman packing in fear does not leave her book in order. She did not go in a hurry.","solves":true}],"riddle":null,"leads":[{"id":"1-2-1","place":"the bottom of her satchel","actions":[{"attr":"Intellect","verb":"empty it out onto the table"},{"attr":"Craft","verb":"feel along the lining"}],"clueTitle":"Bread and a candle","clueText":"In the bottom of the satchel: a heel of bread in a cloth, hard as wood, and a new candle that was never lit.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-2-2","place":"the notebook, page by page","actions":[{"attr":"Intellect","verb":"go through it, leaf by leaf"},{"attr":"Craft","verb":"look at how each page is kept"}],"clueTitle":"Every slip pinned","clueText":"Every loose slip in the notebook is pinned to the page it belongs with. Not one is out of place.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-2-3","place":"the page about the child","actions":[{"attr":"Intellect","verb":"read the page about the child again"},{"attr":"Craft","verb":"look at how the leaf has worn"}],"clueTitle":"The thumbed leaf","clueText":"The leaf about the child is softer than any other in the book, and dark at the corner where a thumb would hold it. She came back to it often.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"They wept for him before they feared him.\"* What turns love for a leader into dread?","weekQuestion":"Why are our names on that list?","pull":"**First light. Two hours north. A child was held at that rock, and whatever it is has not finished.**"}'::jsonb),
('dark-moon', 1, 1, 3, '{"place":"The Widow''s Tooth","narrated":false,"tone":"wry","cupNight":false,"opener":"Smoke over the valley, and a man who bolted the moment he saw you. Sit and catch your breath.","questionTitle":"When he ran for the smoke, was he running home?","forkA":"Fenmark is his.","forkB":"Fenmark is on his way.","callback":"The man on the forest road was carrying her rubbing. The man in the bracken was watching her rock.","nudge":"{friend:Agility}, he ran toward the smoke. What lies that way for a man like him?","nudgeIfLaid":{"piece":"1-3-3","line":"{friend:Aim}, fresh pale notches cut down one side of that stick. What was he keeping count of in the bracken?"},"narratedSilence":null,"puzzle":{"q":"How long has this rock been watched?","clickText":"Someone has sat over this rock for hours at a time, and walked round it often enough to wear the turf away. It is watched, and it has been for a long while."},"clicks":[{"a":"1-3-1","b":"1-3-2","text":"Someone has sat over this rock for hours at a time, and walked round it often enough to wear the turf away. It is watched, and it has been for a long while.","solves":true}],"riddle":null,"leads":[{"id":"1-3-1","place":"the bracken where he waited","actions":[{"attr":"Agility","verb":"crawl into his hollow in the bracken"},{"attr":"Intellect","verb":"read the ground he lay on"}],"clueTitle":"The second ring","clueText":"In the flattened bracken a flask has left a ring in the dew, and a second ring beside it where he set it down again.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"1-3-2","place":"the far side of the rock","actions":[{"attr":"Might","verb":"climb round the split to the far side"},{"attr":"Intellect","verb":"pace out the ground round its foot"}],"clueTitle":"The worn path","clueText":"Round the foot of the rock the turf is worn to bare earth in a narrow path, all the way round. Someone walks round this stone, and often.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"1-3-3","place":"the gap he ran through","actions":[{"attr":"Agility","verb":"run his line to the trees"},{"attr":"Aim","verb":"search the ground he crossed"}],"clueTitle":"The notched stick","clueText":"In the gap where he ran, a stick lies dropped, notched down one side. The newest notches are still pale and wet.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Some locks already know their key.\"* Why shape a lock to wait for someone not yet born?","weekQuestion":"Why are our names on that list?","pull":"The morning is getting on, and this is the Widow''s Tooth. Garrick has not gone back to his inn. He is standing in the road with his pack on, looking at the smoke.\n\n**The ruts go that way. So did the man. He will be there before you, and every door will be shut when you come.**"}'::jsonb),
('dark-moon', 1, 1, 4, '{"place":"Fenmark","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"Why did they take Tamsin, of all the children in Fenmark?","forkA":"She was someone in particular. They came for her.","forkB":"She was the easiest to take.","callback":"The boy says they moved like they''d done it before. The little horse at the rock had sat out a winter or two.","nudge":"{friend:Charm}, of all the children in Fenmark, why her?","nudgeIfLaid":{"piece":"1-4-3","line":"{friend:Charm}, three doors, with children behind them. Why hers?"},"narratedSilence":"Garrick sets a bowl in front of each of you, and for once he says nothing at all.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"1-4-1","place":"the gate at the end of the lane","actions":[{"attr":"Craft","verb":"look at how the gate was left"},{"attr":"Might","verb":"lift the bar and feel its weight"}],"clueTitle":"The leaned bar","clueText":"The gate at the end of the lane is swinging, but its bar has been lifted and leaned neatly against the post, not thrown down.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"1-4-2","place":"the one open shutter","actions":[{"attr":"Charm","verb":"stop at the open shutter and wait"},{"attr":"Aim","verb":"look in from across the lane"}],"clueTitle":"The covered cup","clueText":"On the sill of the open shutter stands a cup of milk with a cloth over it. Under the window, a child''s stool is set square to the wall.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"1-4-3","place":"the boy, at the gate","actions":[{"attr":"Charm","verb":"ask the boy how they came"},{"attr":"Intellect","verb":"ask the boy what they passed"}],"clueTitle":"Past three doors","clueText":"The boy says they came up the lane in the dark and went past three doors with children behind them.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Marked before the first cry''s through.\"* Is a mark like that a gift, or a sentence?","weekQuestion":"Why are our names on that list?","pull":"It is long past noon when Fenmark lets you go, and the light is already thinning over the fen. Behind you, one by one, the shutters close.\n\n**East. Two hours. He has half a day on you, and he is heading for the only other person alive who has seen that knife.**"}'::jsonb),
('dark-moon', 1, 1, 5, '{"place":"The old charcoal camp","narrated":false,"tone":"wry","cupNight":false,"opener":"Two winters between two children. Some people count in winters. It''s a way of keeping still.","questionTitle":"Is it the same man, twice, or a way of working?","forkA":"It''s the same man, twice.","forkB":"It''s a way of working, not one man.","callback":"The road, the rock, and tonight her shutters. Not one of those men has said a word.","nudge":"{friend:Intellect}, she knows him by a knife, and the knife in that camp is a kitchen blade. Which do you trust?","nudgeIfLaid":{"piece":"1-5-1","line":"{friend:Charm}, she never saw his face, only the knife. How many men carry a blade like that?"},"narratedSilence":null,"puzzle":{"q":"Has someone tried her house before tonight?","clickText":"The marks on her back shutter are old and new in the same place, and the bar on her door has worn its cleats deep. Someone has tried her house before tonight, and she has barred it every night for a long time."},"clicks":[{"a":"1-5-2","b":"1-5-3","text":"The marks on her back shutter are old and new in the same place, and the bar on her door has worn its cleats deep. Someone has tried her house before tonight, and she has barred it every night for a long time.","solves":true}],"riddle":null,"leads":[{"id":"1-5-1","place":"the woman at the edge of the firelight","actions":[{"attr":"Charm","verb":"sit with her and let her talk"},{"attr":"Intellect","verb":"ask her what she saw two winters back"}],"clueTitle":"The knife, not the face","clueText":"She says she never saw his face, only the knife, and it is the knife she knows him by.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-5-2","place":"the shutter he was trying","actions":[{"attr":"Craft","verb":"run a thumb along the marks in the wood"},{"attr":"Intellect","verb":"set the old marks beside the new"}],"clueTitle":"Older marks","clueText":"Under his fresh marks on the shutter are older ones, grey with weather, worked in at the same place, where the bar sits.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-5-3","place":"her door","actions":[{"attr":"Craft","verb":"look at how her door is barred"},{"attr":"Aim","verb":"look the door over by the firelight"}],"clueTitle":"The worn bar","clueText":"The bar on her door has worn its cleats deep and pale. She has barred it every night for a long time.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"The power that gives is also the power that takes.\"* What has been given this week, and what has been taken?","weekQuestion":"Why are our names on that list?","pull":"Nobody sleeps much. At first light she walks you to the edge of the camp, and stands on the old charcoal road, grey with frost and ash, and points.\n\n**North. The same man, the same country, the same season. If it comes round like a calendar, the time is now.**"}'::jsonb),
('dark-moon', 1, 1, 6, '{"place":"The Low Ford","narrated":false,"tone":"wry","cupNight":true,"opener":"Six pieces, one map. Eat something before you stare at it.","questionTitle":"Why are our names on that list?","forkA":"We are like the children. They want us too.","forkB":"Meira chose us, to help her find them.","callback":"Meira had this shape on paper before any of you found a piece. Tonight the pieces drew it.","nudge":"{friend:Intellect}, that list has been in your pocket all week. Tell the table what you make of it now.","nudgeIfLaid":{"piece":"1-6-1","line":"{friend:Aim}, woollen threads on a thorn at a child''s height, away from the ruts. Someone carried her along the bank."},"narratedSilence":null,"puzzle":{"q":"Why send the cart one way and the child another?","clickText":"One man carried her down to the water, the other went back up to the cart, and the cart went up the far bank at a run, without her. Anyone who followed the cart was following an empty one."},"clicks":[{"a":"1-6-2","b":"1-6-3","text":"One man carried her down to the water, the other went back up to the cart, and the cart went up the far bank at a run, without her. Anyone who followed the cart was following an empty one.","solves":true}],"riddle":null,"leads":[{"id":"1-6-1","place":"the far bank, along the water","actions":[{"attr":"Aim","verb":"scan the far bank from the ford-stone"},{"attr":"Might","verb":"wade the safe line across"}],"clueTitle":"Threads on a thorn","clueText":"On a thorn at the water''s edge of the far bank, a little way along from the ruts, a few woollen threads hang at the height of a child.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-6-2","place":"the ruts up the far bank","actions":[{"attr":"Craft","verb":"read the hoofprints beside the ruts"},{"attr":"Might","verb":"cross and walk the ruts up the bank"}],"clueTitle":"Up at a run","clueText":"Beside the ruts, the horse''s prints up the far bank are short, deep and dug in at the toe. It went up at a run.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-6-3","place":"the heel-marks at the water","actions":[{"attr":"Agility","verb":"get down to them before the river does"},{"attr":"Intellect","verb":"work out whose feet went where"}],"clueTitle":"A second man","clueText":"Beside the heel-marks, a second man''s prints come down from the cart to the water and go straight back up to it.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"The key that locks.\"* If the same hand can lock or open, how do you know which you were called for?","weekQuestion":"Why are our names on that list?","pull":"**Cross at first light. You will be there by nightfall. Whatever is at the place the map marks, the season for it is now.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 2, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 2, 1, '{"place":"The mine, then the mill road","narrated":false,"tone":"wry","cupNight":true,"opener":"An empty slot in the mine wall, and a cart going down the valley in the dark. Take a place by the coals.","questionTitle":"The cart passed three sleeping farms in the dark and stopped only at the mill. Why?","forkA":"Someone was waiting on the road to guide them in.","forkB":"They had one destination before they ever entered the valley.","callback":"The mine wall put Tamsin''s name first and Corin''s second. Tamsin heard them say \"the mill boy next\".","nudge":"{friend:Aim}, an old man with two winters of firewood split behind him, watching one road. What was he waiting for?","nudgeIfLaid":{"piece":"2-1-3","line":"{friend:Agility}, those ruts at the upriver turn sank deeper coming down than going up. What weight did the cart take out of this valley?"},"narratedSilence":null,"puzzle":{"q":"How did the cart travel in the dark?","clickText":"In full dark and with no lamp, the horse took the fork at a steady walk, and the wheels never checked at any other house in the lane. Either the horse knew the mill road, or someone walked ahead of it."},"clicks":[{"a":"2-1-1","b":"2-1-2","text":"In full dark and with no lamp, the horse took the fork at a steady walk, and the wheels never checked at any other house in the lane. Either the horse knew the mill road, or someone walked ahead of it.","solves":true}],"riddle":null,"leads":[{"id":"2-1-1","place":"the bench by his door","actions":[{"attr":"Charm","verb":"let him tell it his own way"},{"attr":"Intellect","verb":"ask him about the horse, not the men"}],"clueTitle":"The steady horse","clueText":"The old man says the horse never balked at his gate or at the fork, in full dark and with no lamp. It took the mill lane at a steady walk.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-2","place":"the fresh ruts in the lane","actions":[{"attr":"Aim","verb":"follow the ruts past his gate"},{"attr":"Craft","verb":"read where the wheels ran"}],"clueTitle":"Past the gate","clueText":"The ruts run past his gate without a check or a pause, straight toward the mill. The cart did not turn its wheels for any other house in the lane.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-3","place":"where the cart turned upriver","actions":[{"attr":"Agility","verb":"run down to the turn before dark"},{"attr":"Aim","verb":"read the turn in the half-light"}],"clueTitle":"Deeper coming down","clueText":"Where the cart turned upriver, the ruts coming down sink deeper into the verge than the ruts going up.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We held his last wall.\"* If it was meant to fall, why stand on it?","weekQuestion":"Why these children, and not any others?","pull":"**The mill is an hour on. At first light: what did the family see?**"}'::jsonb),
('dark-moon', 1, 2, 2, '{"place":"The mill","narrated":false,"tone":"wry","cupNight":false,"opener":"Asked for by name, and by the night he was born. That''s a strange thing to ask for.","questionTitle":"How did a stranger know the night the boy was born?","forkA":"From an old record kept somewhere far from here.","forkB":"Someone from this valley told him.","callback":"In the mine, that shape was a hole, and what sat in it was gone. Here it''s cut into the mill''s footing.","nudge":"{friend:Craft}, look at that footing stone again. The wheel is fifty years old, but the mark under it is older than the valley. How long has that mark been waiting?","nudgeIfLaid":{"piece":"2-2-3","line":"{friend:Craft}, grass cropped short in a wide half-circle where the cart stood. That horse stood tethered in the yard a long while before anyone went inside."},"narratedSilence":null,"puzzle":{"q":"Did he hesitate once he reached the house?","clickText":"The mud on the floorboards runs in one unbroken line from the door to the child''s bed, and the paper was in his fist before he crossed the threshold. He did not search the house."},"clicks":[{"a":"2-2-1","b":"2-2-2","text":"The mud on the floorboards runs in one unbroken line from the door to the child''s bed, and the paper was in his fist before he crossed the threshold. He did not search the house.","solves":true}],"riddle":null,"leads":[{"id":"2-2-1","place":"the doorway, with her","actions":[{"attr":"Charm","verb":"ask her what was in his hands"},{"attr":"Intellect","verb":"ask her what he did before he spoke"}],"clueTitle":"The paper in his fist","clueText":"She says he had a folded paper in his fist. He looked at it once, then said the boy''s name.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-2","place":"inside the mill door","actions":[{"attr":"Aim","verb":"follow his boot-marks inside"},{"attr":"Craft","verb":"read the dried mud on the boards"}],"clueTitle":"Straight to the bed","clueText":"Nobody has swept since. His dried boot-mud goes from the door straight to the boy''s bed and back, and never turns aside.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-3","place":"the yard where the cart stood","actions":[{"attr":"Aim","verb":"walk the yard by the light from the door"},{"attr":"Craft","verb":"read what the horse left behind"}],"clueTitle":"The cropped grass","clueText":"Where the cart stood in the yard, the grass is cropped short in a wide half-circle, as far as a tethered horse can reach.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"By the third, we had stopped.\"* Did they stop counting because they lost hope, or because the numbers stopped mattering?","weekQuestion":"Why these children, and not any others?","pull":"**Upriver. The ruts are four nights old, and there is weather coming.**"}'::jsonb),
('dark-moon', 1, 2, 3, '{"place":"Upriver","narrated":false,"tone":"wry","cupNight":false,"opener":"A stranger dead at a lock, and the lock opens for you. Stone doesn''t have favorites without a reason.","questionTitle":"The dead man picked at the housing for days. Why did it give under your bare hand?","forkA":"The stone woke to the fragments in our pack.","forkB":"The stone woke to the hand that touched it.","callback":"Corin was asked for by name. Today a lock that wouldn''t open for a dead man opened for you.","nudge":"{friend:Intellect}, a dog chained between two rocks four nights ago, fed fresh meat, and a dead man left on the path. Who is keeping that road?","nudgeIfLaid":{"piece":"2-3-3","line":"{friend:Might}, clean water and fresh meat set behind that dog. Whoever keeps this path was here today."},"narratedSilence":null,"puzzle":{"q":"Why didn''t anyone rob him?","clickText":"He worked that stone for days with steel, and his belt is still weighted with coin. The path-keeper stepped over his body for a week and took neither his tools nor his purse."},"clicks":[{"a":"2-3-1","b":"2-3-2","text":"He worked that stone for days with steel, and his belt is still weighted with coin. The path-keeper stepped over his body for a week and took neither his tools nor his purse.","solves":true}],"riddle":null,"leads":[{"id":"2-3-1","place":"the stone round the housing","actions":[{"attr":"Craft","verb":"look at the stone round the lock"},{"attr":"Intellect","verb":"read the marks cut into it"}],"clueTitle":"The scratches","clueText":"The stone round the housing is scored with dozens of short scratches, some weathered and some bright. He tried it more than once, on more than one day.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-2","place":"the stranger on the path","actions":[{"attr":"Charm","verb":"kneel by him and close his eyes"},{"attr":"Intellect","verb":"go through what he carried"}],"clueTitle":"Silver in his purse","clueText":"His purse is still on his belt, and there is silver in it. A week of people have stepped over him, and not one has taken it.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-3","place":"the narrows where the dog lies","actions":[{"attr":"Might","verb":"hold the chain short and get past"},{"attr":"Aim","verb":"look past the dog from the rocks"}],"clueTitle":"The full pail","clueText":"Behind the dog, at the end of its chain, stands a pail of water, full and clean. There is a scrap of fresh meat beside it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Ours was the last light burning.\"* When every other light has gone out, why keep yours lit?","weekQuestion":"Why these children, and not any others?","pull":"**Where was he trying to get to? The path goes on past him, and up.**"}'::jsonb),
('dark-moon', 1, 2, 4, '{"place":"The shaft in the hillside","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"They pulled the ladder, but they didn''t run. Why didn''t they scatter when we were spotted?","forkA":"They have too many guards down there to fear four people.","forkB":"Whatever they are doing to the boy cannot be paused for anything.","callback":"Yesterday a branch swung on the slope with no wind. Today they knew you were at the shaft.","nudge":"{friend:Charm}, you saw his hands before they hauled the ladder up. Not a scratch on him yet. What are they waiting for?","nudgeIfLaid":{"piece":"2-4-3","line":"{friend:Intellect}, the heads turned when the shout went up, yet the chant never broke. They will not stop for us."},"narratedSilence":"Garrick sets the pot off the coals without a word and sits with his back to the rock, listening to the wind over the hillside.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"2-4-1","place":"the foot of the shaft","actions":[{"attr":"Aim","verb":"look down past the edge"},{"attr":"Agility","verb":"creep back to the lip and look"}],"clueTitle":"The second lamp","clueText":"A second lamp stands lit at the foot of the shaft, filled and trimmed, the same make as the ring in the chamber. Nobody grabbed it in a hurry.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-2","place":"the timbers at the shaft''s mouth","actions":[{"attr":"Craft","verb":"look over the timbering at the top"},{"attr":"Aim","verb":"follow the timber down by the lamplight"}],"clueTitle":"The pale scar","clueText":"On the timbering just below the top, a fresh pale scar runs down the wood, where a stone knocked loose went bouncing all the way to the bottom.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-3","place":"the voices down the shaft","actions":[{"attr":"Aim","verb":"lie flat at the edge and listen"},{"attr":"Intellect","verb":"count the voices as they go round"}],"clueTitle":"The chant ran on","clueText":"When the shout went up, the heads turned, but the chant never stopped. It ran on under the shout the whole time, the same few words.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"His hand was bleeding, and he told us to sleep.\"* What price did he pay down there so they could sleep?","weekQuestion":"Why these children, and not any others?","pull":"**Is there another way into this hill, before they finish? You have tonight to find it.**"}'::jsonb),
('dark-moon', 1, 2, 5, '{"place":"The hillside by night","narrated":false,"tone":"wry","cupNight":false,"opener":"A circle of black cloth, and a man who fought without a word. Somebody wanted a name forgotten.","questionTitle":"Meira found every record of him scraped clean. Who erased his name from the world?","forkA":"His enemies tore his name down to break those who followed him.","forkB":"His own people hid his name to keep what he did a secret.","callback":"On Day 2 a horn button, on Day 3 a dead stranger. Tonight, a circle.","nudge":"{friend:Intellect}, a scout who fights without a sound, tears his own coat to get free, and flashes a lamp twice toward the dark. Who teaches a man to fight like that?","nudgeIfLaid":{"piece":"2-5-1","line":"{friend:Craft}, chisel scars weathered grey where an entire face of stone was ground flat. That took days of open work."},"narratedSilence":null,"puzzle":{"q":"Were the stones broken or hidden?","clickText":"The carved monuments on the ridge were shattered with fire and mallet, but the cut stones in the sheepfold were laid face-inward against each other. Some were broken in anger, and some were hidden with care."},"clicks":[{"a":"2-5-2","b":"2-5-3","text":"The carved monuments on the ridge were shattered with fire and mallet, but the cut stones in the sheepfold were laid face-inward against each other. Some were broken in anger, and some were hidden with care.","solves":true}],"riddle":null,"leads":[{"id":"2-5-1","place":"the old stone where he signalled","actions":[{"attr":"Craft","verb":"run a hand over each face of it"},{"attr":"Aim","verb":"look at it side-on by the lamp"}],"clueTitle":"The ground-flat face","clueText":"On the old stone where the scout stood, one face has been ground flat, long ago. The chisel scars are weathered grey. Whatever was carved there is gone.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-2","place":"the scree below the stone","actions":[{"attr":"Agility","verb":"scramble down the scree"},{"attr":"Aim","verb":"search the scree by lamplight"}],"clueTitle":"Burned chips","clueText":"Mixed into the scree are chips of dressed stone, blackened by fire. One still carries the curve of a carved letter, broken off mid-word.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-3","place":"the fallen sheepfold","actions":[{"attr":"Might","verb":"lift the fallen stones one by one"},{"attr":"Craft","verb":"look at how the fold was built"}],"clueTitle":"Faces turned in","clueText":"The fold''s old cut stones were laid with their carved sides turned inward, against each other, every one. From outside, the wall shows nothing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Not one of us who would not have died for him.\"* Why would those who loved him that deeply become the ones who bound him?","weekQuestion":"Why these children, and not any others?","pull":"**There is no second door on this hillside, and now there is a clock. Last week, six cold slivers showed you a way nobody was watching. You have five.**"}'::jsonb),
('dark-moon', 1, 2, 6, '{"place":"The lip of the shaft","narrated":false,"tone":"wry","cupNight":true,"opener":"Picks in the deep rock. They''re digging toward something that was here before them.","questionTitle":"The fragments drew a map to an older room. Why are they digging toward that same room tonight?","forkA":"They know what is inside that room, and came to take it.","forkB":"They are digging toward the boy, and do not know the old room exists.","callback":"In the mine, you reached the mark after it was emptied. Tonight they''re still digging toward the older room.","nudge":"{friend:Might}, feel that rhythm through the turf. Those picks are driving straight toward the old room under the lamps. What do they think is waiting in it?","nudgeIfLaid":{"piece":"2-6-3","line":"{friend:Agility}, thick dust on the first step down and no print in it but yours. Nobody has gone in by the Seekers'' stair since it was sealed."},"narratedSilence":null,"puzzle":{"q":"What are the picks searching for?","clickText":"The pick-strokes fall in one unbroken line toward the deeper stone, and every basket of earth is sifted through bare fingers. They are not clearing rock for a tunnel. They are searching for something small."},"clicks":[{"a":"2-6-1","b":"2-6-2","text":"The pick-strokes fall in one unbroken line toward the deeper stone, and every basket of earth is sifted through bare fingers. They are not clearing rock for a tunnel. They are searching for something small.","solves":true}],"riddle":null,"leads":[{"id":"2-6-1","place":"the ground over the picks","actions":[{"attr":"Craft","verb":"feel the strokes through the turf"},{"attr":"Intellect","verb":"time the strokes and place them"}],"clueTitle":"One line","clueText":"The strokes come from one place only, and each new stroke lands a little nearer the old shaft than the last.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-2","place":"the two lamps at the foot","actions":[{"attr":"Aim","verb":"watch what passes the lamps"},{"attr":"Agility","verb":"crawl to the edge and look down"}],"clueTitle":"Sifted by hand","clueText":"In the lamplight at the foot of the shaft, baskets of dug earth are tipped out. Someone kneels and sifts each one through their hands before it is thrown aside.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-3","place":"the hole under the old stone","actions":[{"attr":"Might","verb":"shift one more stone"},{"attr":"Agility","verb":"squeeze in to the first step"}],"clueTitle":"Your own print","clueText":"Under the stones, the first step down is thick with dust. In the dust there is no print but your own.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Morning came. The enemy did not.\"* What kind of victory leaves the victors afraid of the morning?","weekQuestion":"Why these children, and not any others?","pull":"**They are digging toward the old room. Be in it first.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 3, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 3, 1, '{"place":"Somewhere warm","narrated":false,"tone":"wry","cupNight":false,"opener":"Somewhere warm. I''d settle for a warm supper. Eat.","questionTitle":"Corin said they promised Wren she was going home first. Why tell a stolen child that?","forkA":"A lie to keep a child quiet and docile on the road.","forkB":"The truth: her home in the burned country is where their work needed her.","callback":"Corin was held a morning''s walk from his own mill. Wren was told she was going home first.","nudge":"{friend:Intellect}, a child''s mitten tucked in Corin''s belt, smelling of sheep. Who gives a mitten to another child in the dark?","nudgeIfLaid":{"piece":"3-1-1","line":"{friend:Charm}, a grey woollen mitten in Corin''s belt that isn''t his. She gave him something to remember her by in the dark."},"narratedSilence":null,"puzzle":{"q":"Did the cart make ready for a long journey?","clickText":"The cart below the shaft took the west road without checking, and on the ridge above the runner paused only to watch that same line. They did not search for a trail. They set their faces toward the burned hills and walked."},"clicks":[{"a":"3-1-2","b":"3-1-3","text":"The cart below the shaft took the west road without checking, and on the ridge above the runner paused only to watch that same line. They did not search for a trail. They set their faces toward the burned hills and walked.","solves":true}],"riddle":null,"leads":[{"id":"3-1-1","place":"Corin, on the walk down","actions":[{"attr":"Charm","verb":"walk beside him and let him talk"},{"attr":"Aim","verb":"look him over in the morning light"}],"clueTitle":"The grey wool","clueText":"Corin has a child''s woollen mitten tucked in his belt that is not his. The wool is rough and grey, and it smells of sheep.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-2","place":"where the cart stood, below the shaft","actions":[{"attr":"Craft","verb":"read what the cart left in the grass"},{"attr":"Intellect","verb":"work out what they loaded"}],"clueTitle":"The fresh turn","clueText":"Where the cart stood below the shaft, the ruts cut clean into the turf, turning west onto the old road without a moment''s pause.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-3","place":"the shoulder of the hill he ran over","actions":[{"attr":"Agility","verb":"go up the shoulder after him"},{"attr":"Aim","verb":"follow his line from the shaft mouth"}],"clueTitle":"Facing west","clueText":"At the top of the shoulder the ground is scuffed where he stood a while, facing west. Then his prints go on, the same way the cart went.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then they stopped being ours.\"* When a weapon stops belonging to the hands that made it, who does it belong to?","weekQuestion":"What do they need Wren for?","pull":"They are not hiding her. They told her she was going home.\n\n**Why would anyone take a stolen child back to where she was born? Ashcombe: a long day west.**"}'::jsonb),
('dark-moon', 1, 3, 2, '{"place":"Ashcombe","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"The men in grey coats spoke politely and promised she''d only be needed once. Was that courtesy genuine?","forkA":"Yes: they take what the rite requires, and let the children go.","forkB":"No: a polite kidnapper is only a kidnapper who hates a scene.","callback":"Tamsin and Corin each came home with one cut palm, bound clean. Wren''s taker said they''d only need her the once.","nudge":"{friend:Charm}, chips of black glass set in a row on her windowsill, dusted around with care. Why leave them behind?","nudgeIfLaid":{"piece":"3-2-3","line":"{friend:Craft}, sacking tied over the hooves to quiet them on the stones. Polite words at the door, and muffled horses in the street."},"narratedSilence":"Garrick sits by the hearth with his boots off, watching the embers in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"3-2-1","place":"the well, and the board of chips","actions":[{"attr":"Charm","verb":"crouch by the board and wait"},{"attr":"Aim","verb":"watch the well from across the street"}],"clueTitle":"The boy at the well","clueText":"At the well a boy holds his chip out low and quick, then shoves it back into his shirt before you have looked at it properly.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-2","place":"the empty cart at the foot of the black road","actions":[{"attr":"Craft","verb":"climb up and look over the boards"},{"attr":"Intellect","verb":"go over the cart end to end"}],"clueTitle":"The made bed","clueText":"In the bed of the empty cart a sheepskin is spread over the boards, and a blanket is folded at one end like a pillow.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-3","place":"the street, where every door shut","actions":[{"attr":"Aim","verb":"walk the street with your eyes on the ground"},{"attr":"Craft","verb":"pick out what is caught between the stones"}],"clueTitle":"Sacking on the stones","clueText":"Caught between the stones down the middle of the street are scraps of sacking. It is the kind men tie over hooves to quiet them on a night road.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Remember that, when you hear where else we stood.\"* What were the five asking future strangers to forgive?","weekQuestion":"What do they need Wren for?","pull":"**What does anyone need a child for, once? The Blackglass: half a day up the black road, the place Meira marked.**"}'::jsonb),
('dark-moon', 1, 3, 3, '{"place":"The Blackglass","narrated":false,"tone":"wry","cupNight":false,"opener":"Mind your hands on that glass, all of you.","questionTitle":"Three children live beside three Seeker marks. Why did the riders carry Wren straight past the Blackglass?","forkA":"They cannot open these ancient housings; they need an older entrance.","forkB":"The marks are not their goal; they are only the guide-stones to the Kiln.","callback":"At the Widow''s Tooth a man lay in the bracken watching the rock. Here the riders went past this one without slowing.","nudge":"{friend:Intellect}, Meira''s note in the margin: ''Five, the fragment says. Every other record says four.'' Why would a scholar write down a number she doubted?","nudgeIfLaid":{"piece":"3-3-3","line":"{friend:Aim}, from the lip of the glass you can see straight down to Ashcombe''s well. Anyone standing here watches the whole village."},"narratedSilence":null,"puzzle":{"q":"Has anyone touched this housing since the road was made?","clickText":"The old shepherds'' path ends dead at the sunken stones, and the fine dust over the housing was undisturbed until your fingers reached it. The riders stayed on the crest and rode past without once looking down."},"clicks":[{"a":"3-3-1","b":"3-3-2","text":"The old shepherds'' path ends dead at the sunken stones, and the fine dust over the housing was undisturbed until your fingers reached it. The riders stayed on the crest and rode past without once looking down.","solves":true}],"riddle":null,"leads":[{"id":"3-3-1","place":"where the shepherds'' path meets the glass","actions":[{"attr":"Intellect","verb":"look at where the path gives out"},{"attr":"Agility","verb":"walk the edge of the glass"}],"clueTitle":"The row of stones","clueText":"Where the shepherds'' path meets the glass, a row of old stones lies across it, sunk deep in the turf. The path stops dead at the row.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-2","place":"the housing beside the mark","actions":[{"attr":"Craft","verb":"run a finger round its carving"},{"attr":"Intellect","verb":"look it over before you step away"}],"clueTitle":"Only your hand","clueText":"The glass round the housing is dull with fine dust. The only marks in it are the ones your own hand just made.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-3","place":"the far edge, where the glass is cracked","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Might","verb":"climb onto the highest lip of glass"}],"clueTitle":"The view down","clueText":"From the far edge you can see all the way down the black road to Ashcombe''s roofs, and the well in the middle of them.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"He only never told us the price.\"* Did he hide the price to spare them, or because they would have refused him?","weekQuestion":"What do they need Wren for?","pull":"**They rode straight past the one thing Meira marked. So what are they riding to? On, into the black ridges.**"}'::jsonb),
('dark-moon', 1, 3, 4, '{"place":"The black ridges","narrated":false,"tone":"wry","cupNight":true,"opener":"Whoever slept in these niches had long nights too. Build the fire in the doorway.","questionTitle":"Wren is dropping glass chips from the saddle of six horses. Have the riders truly not noticed?","forkA":"They believe a small child is helpless and don''t watch her hands.","forkB":"They see the chips, but know the trail ends where no one can follow.","callback":"Tamsin wasn''t asleep; she was counting. Wren is dropping her chips, one by one, on their trail.","nudge":"{friend:Craft}, each glass chip set on high bare rock beside the tallest dead tree, and scratched on the back in order. Why number a trail unless she expects us to read it?","nudgeIfLaid":{"piece":"3-4-2","line":"{friend:Aim}, every chip dropped beside the tallest dead tree in sight, each visible from the last. She was sighting her own line as she rode."},"narratedSilence":null,"puzzle":{"q":"Did she drop the chips in haste or with care?","clickText":"Each chip was set on high bare rock where the starlight catches it, and the backs are scored with tiny knife-scratches: one, two, three. She is laying a numbered line across the dark."},"clicks":[{"a":"3-4-1","b":"3-4-3","text":"Each chip was set on high bare rock where the starlight catches it, and the backs are scored with tiny knife-scratches: one, two, three. She is laying a numbered line across the dark.","solves":true}],"riddle":null,"leads":[{"id":"3-4-1","place":"the rises along the riders'' trail","actions":[{"attr":"Aim","verb":"look back down the trail from the last rise"},{"attr":"Agility","verb":"run the trail back to the first chip"}],"clueTitle":"On the bare rock","clueText":"Each chip lay on bare rock at the top of a rise, never down in the ash where it would sink. Coming up behind, you see each one glint before you reach it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-2","place":"the bone-white trees along the trail","actions":[{"attr":"Intellect","verb":"set each chip beside what stood near it"},{"attr":"Aim","verb":"look round from where each one lay"}],"clueTitle":"A tree at each","clueText":"Each chip lay a few paces from a dead tree, the tallest one in sight. Stand at one tree, and you can see the next.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-3","place":"the three chips in your hand","actions":[{"attr":"Craft","verb":"turn each one over in the light"},{"attr":"Intellect","verb":"lay them out side by side"}],"clueTitle":"Scratched on the back","clueText":"Turn the chips over. One has a single short scratch on its back, one has two, and one has three.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We locked with what we are.\"* Why bind a lock in living blood instead of stone or iron?","weekQuestion":"What do they need Wren for?","pull":"**She is alive, and she is thinking. The hut, at first light.**"}'::jsonb),
('dark-moon', 1, 3, 5, '{"place":"The shepherd''s hut","narrated":false,"tone":"wry","cupNight":false,"opener":"For the first time all season, they ran. Sit down and breathe.","questionTitle":"They gave Wren the warm bed by the hearth, yet fled in the night leaving their pot on the fire. What made them run?","forkA":"Fear: our fire on the ridge showed them they were being hunted.","forkB":"The hour: the time for waiting expired, and the Kiln must be lit.","callback":"At the mine someone took the time to bind Tamsin''s hand in clean linen. Here someone folded one blanket with care, and threw the other down.","nudge":"{friend:Might}, cut deep into the beam over her bed: ''Until the throne rise whole.'' Who carves a prayer over a stolen child''s pillow?","nudgeIfLaid":{"piece":"3-5-1","line":"{friend:Craft}, each letter of her name cut twice into the doorframe. She wanted that mark to outlast the hut."},"narratedSilence":null,"puzzle":{"q":"How quickly did they depart?","clickText":"By the spring a full water skin lies abandoned where it was dropped, while inside the hut Wren''s keepsakes were left undisturbed in their row on the sill. The hurry was sudden, but it began outside the room."},"clicks":[{"a":"3-5-2","b":"3-5-3","text":"By the spring a full water skin lies abandoned where it was dropped, while inside the hut Wren''s keepsakes were left undisturbed in their row on the sill. The hurry was sudden, but it began outside the room.","solves":true}],"riddle":null,"leads":[{"id":"3-5-1","place":"low on the doorframe","actions":[{"attr":"Craft","verb":"run a thumbnail along the letters"},{"attr":"Intellect","verb":"look at how each letter was made"}],"clueTitle":"Cut twice","clueText":"Each stroke of the name has been cut twice, the second pass deeper than the first.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-2","place":"the spring below the hut","actions":[{"attr":"Agility","verb":"get down to the water fast"},{"attr":"Aim","verb":"look over the ground by the spring"}],"clueTitle":"The dropped skin","clueText":"By the spring a water skin lies in the grass, half full. Its stopper is a pace away.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-3","place":"the wall beside the pallet","actions":[{"attr":"Charm","verb":"sit on the pallet and look round"},{"attr":"Intellect","verb":"look at what is kept by the bed"}],"clueTitle":"The gap in the row","clueText":"Along the wall by the pallet, small things are set out in a row: a twist of grey wool, a white pebble, a hen''s feather. At one end there is a gap, and the dust there is clean.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"That is why kingdoms fear them.\"* Why would a kingdom fear a quiet line of families after the war was won?","weekQuestion":"What do they need Wren for?","pull":"**A step, now, and no more. If they could see you, can you see them? The cairn on the highest ridge, before the light goes.**"}'::jsonb),
('dark-moon', 1, 3, 6, '{"place":"The cairn","narrated":false,"tone":"wry","cupNight":false,"opener":"Fire''s built up. Sit by it before you decide anything.","questionTitle":"An hour after we read the map into the wind, a single lamp climbed the Kiln and went inside. Who carried it?","forkA":"A watcher who heard our voices and went in to warn the others.","forkB":"The last of the faithful arriving for the ritual, unaware of us.","callback":"Corin said Wren''s home was always warm. Tonight the map ends at a hill that breathes warm air.","nudge":"{friend:Agility}, one lamp went into that hill an hour after we spoke the map, and now smoke is rising from the crown. Did our voices call them in, or was the fire already laid?","nudgeIfLaid":{"piece":"3-6-3","line":"{friend:Agility}, loose scree on both sides of the knife-edge now the light has gone. Whoever climbed that hill tonight knew every stone by heart."},"narratedSilence":null,"puzzle":{"q":"Are the riders still inside the hill?","clickText":"No horses wait outside in the dark, and from the crown''s crack thin pale smoke has begun to rise into the cold air. The lamp has reached the deep chamber, and the hearth is burning."},"clicks":[{"a":"3-6-1","b":"3-6-2","text":"No horses wait outside in the dark, and from the crown''s crack thin pale smoke has begun to rise into the cold air. The lamp has reached the deep chamber, and the hearth is burning.","solves":true}],"riddle":null,"leads":[{"id":"3-6-1","place":"the foot of the round hill","actions":[{"attr":"Aim","verb":"look down at the foot of the hill"},{"attr":"Intellect","verb":"go over every shape below the crown"}],"clueTitle":"No horses","clueText":"Not one horse is tethered at the foot of the Kiln.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-2","place":"the crack across its crown","actions":[{"attr":"Aim","verb":"watch the crown after the lamp goes in"},{"attr":"Intellect","verb":"watch the air over the crack"}],"clueTitle":"Smoke from the crack","clueText":"Soon after the lamp goes in, thin pale smoke starts to rise from the crack. By daylight there was only shimmering air.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-3","place":"the knife-edge below the cairn","actions":[{"attr":"Agility","verb":"go a little way back along the edge"},{"attr":"Might","verb":"test the stones of the face"}],"clueTitle":"No way down in the dark","clueText":"Now the light has gone, the knife-edge below the cairn is a black line with nothing either side. The face beside it drops straight to loose scree.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"We never dug him a grave.\"* Why seal a hall over someone instead of burying him?","weekQuestion":"What do they need Wren for?","pull":"**Whatever happens under that hill has started. Into the Kiln, tonight.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 4, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 4, 1, '{"place":"Under the Kiln, then Ashcombe","narrated":false,"tone":"wry","cupNight":false,"opener":"Count yourselves. I will, too.","questionTitle":"Someone stood among us in the dark with a bare blade, yet cut only rope. Why spare us?","forkA":"A lone rescuer couldn''t risk a fight in the dark without losing the prisoner.","forkB":"They had us at their mercy and were under orders not to harm us.","callback":"Every one of them you''ve fought has run at the first gap. Tonight one stood among you with a blade and cut only rope.","nudge":"{friend:Craft}, cut rope ends all clean on the same side, a finger''s width from the knot. Someone stepped out of that passage with a steady blade.","nudgeIfLaid":{"piece":"4-1-2","line":"{friend:Aim}, he knelt three paces from that dark passage mouth the whole time. Did he choose that spot himself?"},"narratedSilence":null,"puzzle":{"q":"How did the prisoner get free in the dark?","clickText":"A lamp was just snuffed inside the side passage, and every rope was severed cleanly on the same side a finger''s width from the knot. A second person stepped out of the passage in the dark and cut him loose."},"clicks":[{"a":"4-1-1","b":"4-1-3","text":"A lamp was just snuffed inside the side passage, and every rope was severed cleanly on the same side a finger''s width from the knot. A second person stepped out of the passage in the dark and cut him loose.","solves":true}],"riddle":null,"leads":[{"id":"4-1-1","place":"the passage none of you had noticed","actions":[{"attr":"Agility","verb":"go a few steps in, without a lamp"},{"attr":"Intellect","verb":"stand in its mouth and take stock"}],"clueTitle":"The snuffed wick","clueText":"A few steps into the passage the air smells of a wick just put out. None of your lamps has been in there.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-2","place":"the place where he knelt","actions":[{"attr":"Aim","verb":"pace it out from the passage"},{"attr":"Intellect","verb":"work out what he could reach from there"}],"clueTitle":"Three paces","clueText":"Where he knelt is three paces from the passage mouth, in the corner your lamps lit least.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-3","place":"the ropes on the stone","actions":[{"attr":"Craft","verb":"lay the cut ends side by side"},{"attr":"Might","verb":"pick them up and test each one"}],"clueTitle":"The same side","clueText":"Every rope is cut a finger''s width from its knot, and every cut is on the same side.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We did not trust four locks to hold what needed five.\"* Why scatter four locks across the land and hide the fifth alone?","weekQuestion":"Why has the Order left us alive?","pull":"*Already with us.* Joss is not waiting to be taken.\n\n**A blade within arm''s reach, in the dark, and it cut rope. Why are you still alive? The north road, at first light.**"}'::jsonb),
('dark-moon', 1, 4, 2, '{"place":"The north road","narrated":false,"tone":"wry","cupNight":true,"opener":"Cold road. Put your hands round that cup.","questionTitle":"Four armed riders guarded one small box from the Kiln, riding away from the lake. Why guard that box harder than the boy?","forkA":"The box holds what they actually came for; the child only wakes it.","forkB":"The cart was an open-road decoy meant to draw our eyes off the lake.","callback":"The carter''s coin has the king''s face scraped off. Meira wrote that every record of him had been scraped clean.","nudge":"{friend:Intellect}, bare swords across their saddles and eyes never leaving a single small box in the cart-bed. Why ride like that in broad daylight?","nudgeIfLaid":{"piece":"4-2-1","line":"{friend:Intellect}, the carter says not one of the four looked at the lake or the road—every eye stayed on that box. What rides in a box like that?"},"narratedSilence":null,"puzzle":{"q":"Were the four riders trying to hide their journey north?","clickText":"They rode the ford in broad daylight with bare blades across their saddles, and kept to the open road past every hut when the ridge sheep-path would have hidden them. They were either daring anyone to stop them, or making sure the cart was seen."},"clicks":[{"a":"4-2-2","b":"4-2-3","text":"They rode the ford in broad daylight with bare blades across their saddles, and kept to the open road past every hut when the ridge sheep-path would have hidden them. They were either daring anyone to stop them, or making sure the cart was seen.","solves":true}],"riddle":null,"leads":[{"id":"4-2-1","place":"the carter, watering his horses","actions":[{"attr":"Charm","verb":"let him run on about the riders"},{"attr":"Intellect","verb":"ask how the four rode"}],"clueTitle":"Every eye on the cart","clueText":"The carter says the four never spoke to each other, and never once looked at the road or the lake. Every eye stayed on the cart.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-2","place":"the men in the shallows","actions":[{"attr":"Charm","verb":"sit down in the water with them"},{"attr":"Intellect","verb":"ask what made them let it pass"}],"clueTitle":"Blades bare","clueText":"They say the four came through the ford with their blades bare across their saddles, in full daylight, and did not slow down.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-3","place":"the ruts going north","actions":[{"attr":"Aim","verb":"follow them as far as the light lets you"},{"attr":"Craft","verb":"read where they could have turned off"}],"clueTitle":"The open road","clueText":"Their ruts keep to the open road the whole way, past every shepherd''s hut. A sheep-path along the ridge would have hidden them from all of it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We feared it more than the other four together.\"* Why would the Seekers fear one of their own creations above the rest?","weekQuestion":"Why has the Order left us alive?","pull":"**Four armed men for one small box, riding away from the boy. What is in it? Reedham, by noon tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 3, '{"place":"Reedham","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"They took Joss eight nights ago — before we even reached the Kiln — and have kept him on the water ever since. What are they waiting for?","forkA":"A night or a water-level that hasn''t come yet to reach the drowned chamber.","forkB":"Someone else who had not reached Reedham yet: they have been waiting for us.","callback":"In Ashcombe a baby born when the moon goes out is given a chip of black glass. In Reedham every window is lit for one.","nudge":"{friend:Craft}, eight notches cut in her doorpost wood, and a boat heavier than her skiff touching the shingle by night.","nudgeIfLaid":{"piece":"4-3-3","line":"{friend:Aim}, weed scraped clean off the lowest sill facing Reedham. Someone sat in that dark tower watching the village before we ever arrived."},"narratedSilence":"Garrick sits by the window looking out over the water, his arms folded in the quiet room.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-3-1","place":"the fisherman on the shingle","actions":[{"attr":"Charm","verb":"help him with his nets and listen"},{"attr":"Intellect","verb":"ask what he hears at night"}],"clueTitle":"The oars at dusk","clueText":"On the shingle the fisherman says he hears oars out on the lake every night, at the same hour, just after dusk. He has never gone to look.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-2","place":"the fresh keel-marks on the shingle","actions":[{"attr":"Craft","verb":"measure the groove against her skiff''s keel"},{"attr":"Intellect","verb":"read how deep the bow bit into the wet stones"}],"clueTitle":"Heavier than her skiff","clueText":"The fresh keel-marks beside her skiff are wider and cut twice as deep into the shingle. Whatever boat touched shore here was carrying four or five people, not one.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-3","place":"the tower''s lowest window","actions":[{"attr":"Agility","verb":"climb up to the sill from the skiff"},{"attr":"Aim","verb":"look it over from the water"}],"clueTitle":"A cleared sill","clueText":"On the tower''s lowest sill, on the side facing the shore road, the weed is scraped away in a patch the size of a seat. Someone has sat here in the dark looking back toward Reedham.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"So does anyone born in its dark.\"* What does a child born under a dark moon share with what fell that night?","weekQuestion":"Why has the Order left us alive?","pull":"Back on the shingle, beside the place her skiff was lying, there are keel-marks that are not hers. Fresh ones, pressed deep into the wet stones, and the lapping of the lake has not yet smoothed them.\n\nUp the lane, the lamp burns on in her window, small and steady in the afternoon.\n\n**Someone has been rowing out to the drowned village by night. Old Reedham, at the shallow end, tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 4, '{"place":"Old Reedham","narrated":false,"tone":"wry","cupNight":false,"opener":"Drowned roofs under the keel, and a page of Meira''s notes that survived the ash. Let''s hear what you found.","questionTitle":"Meira''s note says ''moon-blood'' is the old word for the marked, and the fragment warns against letting it near. What is the fragment warning against?","forkA":"Letting a marked child''s blood touch the Stones — the Order is doing what the Seekers feared.","forkB":"Letting a specific bloodline from the old songs near — ''moon-blood'' may mean more than the birth-mark.","callback":"At the ford, Tamsin''s small prints stopped at the water. Today Joss''s stop at the edge of deep water.","nudge":"{friend:Intellect}, she copied ''the marked'' on one page and ''moon-blood'' on another, then crossed out her second line in the margin until the nib tore through.","nudgeIfLaid":{"piece":"4-4-1","line":"{friend:Craft}, the same iron lamp-hooks in the drowned windows below the water as in Reedham''s windows tonight. The village moved up the bank, and kept the old watch."},"narratedSilence":null,"puzzle":{"q":"Was Meira sure of her own note on ''moon-blood''?","clickText":"Meira copied ''the marked'' and ''moon-blood'' from two separate old records, and under her gloss she began a second thought before scratching it out through the paper. She had a second thought she never finished."},"clicks":[{"a":"4-4-2","b":"4-4-3","text":"Meira copied ''the marked'' and ''moon-blood'' from two separate old records, and under her gloss she began a second thought before scratching it out through the paper. She had a second thought she never finished.","solves":true}],"riddle":null,"leads":[{"id":"4-4-1","place":"the drowned windows","actions":[{"attr":"Aim","verb":"look along the windows in the low light"},{"attr":"Craft","verb":"look at the iron in each frame"}],"clueTitle":"The old hooks","clueText":"In every drowned window frame is the same iron lamp-hook that hangs in Reedham''s windows today. Each one is black with old soot.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-2","place":"the earlier pages of her notes","actions":[{"attr":"Intellect","verb":"go back through them, page by page"},{"attr":"Craft","verb":"set the copied hands side by side"}],"clueTitle":"Two records","clueText":"Two pages back, she copied \"the marked\" out of a different record. The two words never appear in the same copied line.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-3","place":"the margin of her page","actions":[{"attr":"Intellect","verb":"read her note against the line"},{"attr":"Aim","verb":"hold the page to the lamp"}],"clueTitle":"The scratched line","clueText":"Under her note she began a second line, then scratched it out so hard the nib went through the paper.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"If it is ever let near.\"* Were the Seekers warning against their enemies, or against their own children returning?","weekQuestion":"Why has the Order left us alive?","pull":"**A warning against what? The reed island, a mile out: the only place on this lake a boat can put in unseen.**"}'::jsonb),
('dark-moon', 1, 4, 5, '{"place":"The reed island","narrated":false,"tone":"wry","cupNight":false,"opener":"Pale curls of whittled wood. Somebody''s still carving.","questionTitle":"They ferry Joss between the island and the drowned streets by night, yet tonight a lamp is crossing to the empty tower. Why the tower tonight?","forkA":"They shift their watch-post across the lake so no one on shore can fix where the boy is held.","forkB":"They know we took their boat on the island today and are setting a watch for us at the tower.","callback":"At the Widow''s Tooth a little carved horse was left behind. Today, in their boat, a little carved hull was thrown away.","nudge":"{friend:Aim}, three willow cuts—one grey, one brown, one white—and tonight a single lamp moving out toward the tower.","nudgeIfLaid":{"piece":"4-5-2","line":"{friend:Craft}, a dry blanket folded small under the stern seat, out of the spray. They are keeping the boy warm while they wait."},"narratedSilence":null,"puzzle":{"q":"How has Joss been kept on the reed island?","clickText":"The willow has had fresh shoots cut three days running, and the long shavings in the boat''s bilge were carved without haste. They have kept him dry and unharmed on the island by day while moving him across the lake by night."},"clicks":[{"a":"4-5-1","b":"4-5-3","text":"The willow has had fresh shoots cut three days running, and the long shavings in the boat''s bilge were carved without haste. They have kept him dry and unharmed on the island by day while moving him across the lake by night.","solves":true}],"riddle":null,"leads":[{"id":"4-5-1","place":"the rope in the bottom of their boat","actions":[{"attr":"Craft","verb":"sift the shavings out of the rope"},{"attr":"Intellect","verb":"look at how each one was cut"}],"clueTitle":"Long curls","clueText":"Every curl in the bottom of the boat is long and unbroken, and all of them are fresh. Nobody hurried him.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-2","place":"the stern seat","actions":[{"attr":"Craft","verb":"feel under the thwart"},{"attr":"Might","verb":"lift the seat board out"}],"clueTitle":"Folded dry","clueText":"Under the stern seat, out of the spray, a blanket is folded small. It is dry.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-3","place":"the willows at the water''s edge","actions":[{"attr":"Agility","verb":"work along the bank through the willows"},{"attr":"Craft","verb":"look at where the wood was cut"}],"clueTitle":"Three shoots","clueText":"One willow has had three straight shoots cut from it with a sharp blade. One cut is grey, one is brown, and one is still white.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Pray no one ever learns it is also a door.\"* Why build a lock that can still be opened like a door?","weekQuestion":"Why has the Order left us alive?","pull":"**Why would anyone keep watch on an empty tower? After that lamp, tonight, in their own boat.**"}'::jsonb),
('dark-moon', 1, 4, 6, '{"place":"The tower at night","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"A boat lay in the black water right under the tower wall while the map was read aloud. Why was it waiting under an empty tower?","forkA":"They posted a listener at the tower waiting for us to assemble the map and speak the way aloud.","forkB":"They were keeping watch on the shore road and hid under the wall when they heard our oars.","callback":"Yesterday you took their boat. Tonight someone took your words.","nudge":"{friend:Aim}, water rings spreading under the stones while our oars were already still, and a brief light out toward the island. Someone was down there before us.","nudgeIfLaid":{"piece":"4-6-2","line":"{friend:Aim}, one brief light low on the water toward the island, then dark again. Whoever was under our wall signalled across the lake."},"narratedSilence":"Garrick stands in the doorway looking out into the mist where the water laps at the wall.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-6-1","place":"the dark water under the wall","actions":[{"attr":"Aim","verb":"watch the water as you tie up"},{"attr":"Agility","verb":"lean out over the stones"}],"clueTitle":"The rings","clueText":"As you tie up at the tower, rings are already spreading from the dark under its wall, and your oars have been still for a minute.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-2","place":"the empty windows of the bell-chamber","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Intellect","verb":"watch the water you crossed"}],"clueTitle":"One light","clueText":"Out toward the island, low on the water, a light shows for a breath and goes out. It does not show again.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-3","place":"the lights of Reedham","actions":[{"attr":"Aim","verb":"pick out every light on the shore"},{"attr":"Charm","verb":"watch the shore with the others, quietly"}],"clueTitle":"The lamp on the shingle","clueText":"Down on the shore, one lamp moves slowly along the shingle. It stops below her lane, and stays there.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We never asked what that would make them.\"* What debt did the five pass down to children they would never meet?","weekQuestion":"Why has the Order left us alive?","pull":"**Down the stair, into the boat you took from them, and after that sound. Now.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 5, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 5, 1, '{"place":"Reedham, and the waystone","narrated":false,"tone":"wry","cupNight":false,"opener":"North, then. That''s a long road for tired boots.","questionTitle":"The Seekers scattered four Stones to the far corners of the land, yet left the fifth at Highwall. Why keep it in the dead city?","forkA":"They kept the fifth at Highwall to stand guard over him where he fell.","forkB":"The fifth could not be carried away from Highwall without waking him.","callback":"Meira looked for a fifth and never found one. Today, on the road north, somebody had cut a line out of a stone.","nudge":"{friend:Intellect}, the miles left standing on the stone, and the second line under Highwall cut away to the last letter. Whose name sat under the city''s?","nudgeIfLaid":{"piece":"5-1-3","line":"{friend:Charm}, every window in Reedham lit at midday as if the dark moon were tonight. The whole village felt that first beat."},"narratedSilence":null,"puzzle":{"q":"Was the waystone only a road marker, or part of the Seekers'' trail?","clickText":"The line under HIGHWALL was chiselled clean away like the king''s face on the coin, and the crack at the stone''s foot holds the same unnatural cold as every Seeker housing. The road marker was defaced, and the Seekers set their first sign in its foot."},"clicks":[{"a":"5-1-1","b":"5-1-2","text":"The line under HIGHWALL was chiselled clean away like the king''s face on the coin, and the crack at the stone''s foot holds the same unnatural cold as every Seeker housing. The road marker was defaced, and the Seekers set their first sign in its foot.","solves":true}],"riddle":null,"leads":[{"id":"5-1-1","place":"the worn face of the waystone","actions":[{"attr":"Craft","verb":"run a thumb along the cut-away line"},{"attr":"Intellect","verb":"hold the light low and look at its edges"}],"clueTitle":"The crisp edge","clueText":"Frost has eaten the old carving, but the edges of the cut-out line are crisp. Not one letter of it is left.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-2","place":"the crack at the waystone''s foot","actions":[{"attr":"Craft","verb":"scrape back the rime with a knife"},{"attr":"Aim","verb":"watch the crack while the beat comes"}],"clueTitle":"The rime stays","clueText":"Long after the fragment is out, the rime stays in the crack, in a mild wind. It is the same cold you have felt at every hiding place since the forest road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-3","place":"the lane up from the shingle","actions":[{"attr":"Charm","verb":"walk up the lane and stop at a door"},{"attr":"Aim","verb":"look up the lane from the boat"}],"clueTitle":"Every window lit","clueText":"Every window up the lane has a lamp burning at midday, as Reedham does only on a dark-moon night.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"He gave us the war. Then it began to take.\"* When did they realize the man they followed was no longer the man they knew?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay that night in Reedham. Up the lane, the lamp burns on in her window.\n\nAt dusk the heartbeat comes again, up through the floorboards and into the legs of your chair. It is louder than it was at dawn.\n\n**What is left in a city where nothing grows and nobody goes? The old kingdom''s road: two days north.**"}'::jsonb),
('dark-moon', 1, 5, 2, '{"place":"The old kingdom''s road","narrated":false,"tone":"wry","cupNight":false,"opener":"The grass on a war grave shouldn''t shiver. I''d say that''s the heartbeat.","questionTitle":"The heartbeat comes from Highwall for a few slow strokes at dusk and dawn, then stops. What is keeping him from waking outright?","forkA":"The four Stones have only thinned his sleep; it takes a certain night for him to wake.","forkB":"The fifth Stone is still in Highwall, holding the last of the Seekers'' lock shut.","callback":"On the Stillwater the birds went quiet at the first beat. Tonight the dogs came with it.","nudge":"{friend:Might}, one deep bite that held without tearing, and tracks that scattered the moment the beat died. What drove those dogs?","nudgeIfLaid":{"piece":"5-2-2","line":"{friend:Craft}, teeth sunk deep once and held without tearing. That dog wasn''t feeding—it was holding him in place."},"narratedSilence":null,"puzzle":{"q":"Were the dogs hunting for themselves?","clickText":"The dogs came in a straight line from the north while the ground beat, froze mid-stride the instant the beat stopped, and scattered every way after. The beat drove them while it lasted, and let them go when it stopped."},"clicks":[{"a":"5-2-1","b":"5-2-3","text":"The dogs came in a straight line from the north while the ground beat, froze mid-stride the instant the beat stopped, and scattered every way after. The beat drove them while it lasted, and let them go when it stopped.","solves":true}],"riddle":null,"leads":[{"id":"5-2-1","place":"the edge of the dark, past the cart","actions":[{"attr":"Aim","verb":"watch them at the edge of the dark"},{"attr":"Might","verb":"stand over the cart and hold your ground"}],"clueTitle":"Heads down","clueText":"When the beat stops, every dog stops with it, heads down, mid-stride. Not one runs away, and not one comes on.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-2","place":"the bandage on the man''s forearm","actions":[{"attr":"Charm","verb":"ask to see the arm"},{"attr":"Craft","verb":"tie the bandage again, properly"}],"clueTitle":"One bite","clueText":"Under the bandage is a single bite, deep and clean. The teeth went in once and held, and nothing tore.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-3","place":"where the dogs came out of the dusk","actions":[{"attr":"Aim","verb":"read the ground at first light"},{"attr":"Intellect","verb":"walk their tracks back the way they came"}],"clueTitle":"Scattered","clueText":"At first light their tracks come in together, in a straight line from the north. They go out scattered every way, the prints far apart.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"That is why it had to be us.\"* Why could only his closest five be the ones to turn the key?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The heartbeat is nearer every dusk, and it is coming from inside the city. Highwall, by noon.**"}'::jsonb),
('dark-moon', 1, 5, 3, '{"place":"The herald''s gate","narrated":false,"tone":"wry","cupNight":false,"opener":"High on the wall, and not a breath of green in the whole city. Sit down out of the wind.","questionTitle":"Highwall''s gate is barred from the inside with fresh timber in brackets worn bright by centuries of bars. Who is keeping it shut?","forkA":"The Order — keeping the dead city shut so no outsider disturbs their watch on the hall.","forkB":"Wardens left behind on the Seekers'' wall — barring the gate to keep what is inside from getting out.","callback":"Upriver, somebody kept a hidden path clear and a dog on new iron. Here somebody keeps a new bar on an old gate.","nudge":"{friend:Craft}, a broken stair knocked out with hammers long ago, and a fresh timber bar below. Somebody wants only one way in.","nudgeIfLaid":{"piece":"5-3-3","line":"{friend:Craft}, the gatehouse stair knocked out with hammers long ago, while the timber bar below is fresh. Whoever bars that gate never meant to climb the wall."},"narratedSilence":null,"puzzle":{"q":"Was the gate barred long ago and left, or is someone tending it now?","clickText":"The timber bar was felled and squared within the last few days, and a single narrow path is trodden in the dust from the gatehouse straight up toward the smoke. Whoever tends the fire below the hall comes down to bar this gate."},"clicks":[{"a":"5-3-1","b":"5-3-2","text":"The timber bar was felled and squared within the last few days, and a single narrow path is trodden in the dust from the gatehouse straight up toward the smoke. Whoever tends the fire below the hall comes down to bar this gate.","solves":true}],"riddle":null,"leads":[{"id":"5-3-1","place":"the street behind the gate","actions":[{"attr":"Aim","verb":"look down into the street from the walkway"},{"attr":"Agility","verb":"lean out over the inner parapet"}],"clueTitle":"One trodden path","clueText":"In the dust of the street behind the gate, one narrow path is trodden from the bar up the hill, toward the smoke.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-2","place":"the near end of the new bar","actions":[{"attr":"Aim","verb":"pick out the bar''s end from above"},{"attr":"Craft","verb":"judge the timber by its colour"}],"clueTitle":"Still white","clueText":"The bar''s cut end is still white, and the axe-marks are sharp. It was put up within the last few days.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-3","place":"the broken stair","actions":[{"attr":"Agility","verb":"climb down to the gap in the stair"},{"attr":"Craft","verb":"look at the broken edges"}],"clueTitle":"Knocked out","clueText":"The missing steps lie at the stair''s foot in big, square pieces. Every break shows the bite of a hammer, weathered smooth.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"None of us gave to the fifth.\"* If none of the five gave to the fifth Stone, whose was it?","weekQuestion":"What will it take for the fifth to end this?","pull":"You spend the night up on the wall-walk, in the lee of the parapet, with the barred gate beneath you and that one thread of smoke going up into the dark.\n\n**Who bars a dead city from the inside, year after year? Down into the streets, following the wall.**"}'::jsonb),
('dark-moon', 1, 5, 4, '{"place":"The dead streets","narrated":false,"tone":"quiet","cupNight":true,"opener":null,"questionTitle":"Their boots have not stirred the dust in centuries, yet at dusk a helm seemed to turn and metal scraped on stone. Are the standing soldiers waking?","forkA":"No — the dust around every boot is unbroken, and their crooked helms only looked turned in the dusk.","forkB":"Yes — the heartbeat from the hall is beginning to stir them inside their armour.","callback":"On the road, when the beat stopped, the dogs stopped where they stood. These soldiers stopped mid-stride, and never started again.","nudge":"{friend:Aim}, unbroken dust round every boot, and one sound of iron on stone after we barred the door.","nudgeIfLaid":{"piece":"5-4-2","line":"{friend:Agility}, one scrape of iron on stone after the door was barred, and then silence. Something in that street shifted when the beat came."},"narratedSilence":"Garrick wipes the dust from the cups with his sleeve, pours one more than there are of you, and sets the last at the empty place by the shuttered window facing up the hill. \"Family habit. We always pour one for whoever can''t be with us.\"","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"5-4-1","place":"the ground round the soldiers","actions":[{"attr":"Aim","verb":"look at the street round them"},{"attr":"Craft","verb":"crouch and look at the dust"}],"clueTitle":"Unbroken dust","clueText":"Round every boot the dust lies in one even skin. The only prints in it are yours.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-2","place":"the barred door of the empty house","actions":[{"attr":"Aim","verb":"keep an eye to the crack in the door"},{"attr":"Agility","verb":"sit by the door, ready, and listen"}],"clueTitle":"Metal on stone","clueText":"As the light goes, one sound comes from the direction of the street of soldiers: metal on stone, once. Then nothing.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-3","place":"the helms down the street","actions":[{"attr":"Aim","verb":"look along the line of helms"},{"attr":"Intellect","verb":"set each helm against the next"}],"clueTitle":"No two alike","clueText":"Every helm sits a little crooked on its neck, this way or that, no two the same. From the end of the street, any one of them could look turned.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We left them standing.\"* Why leave an entire army standing in the streets instead of laying them to rest?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Was that helm turned before? Nobody is sure. And the smoke is higher up the hill. The square below the hall.**"}'::jsonb),
('dark-moon', 1, 5, 5, '{"place":"Below the hall","narrated":false,"tone":"wry","cupNight":false,"opener":"One chalk stroke each dusk. Somebody''s counting.","questionTitle":"The Order has camped facing the sealed doors for generations, crossing off one stroke each dusk. What are they counting to?","forkA":"A fixed night on the calendar that they have known from the beginning.","forkB":"A sign from inside the hall as the heartbeat grows strong enough to break the seal.","callback":"At Reedham they kept Joss eight nights, waiting for something. Here they strike off one night every dusk.","nudge":"{friend:Intellect}, every stroke on that board drawn in the same square hand, and every head lifting when the beat comes. What ends when the count ends?","nudgeIfLaid":{"piece":"5-5-3","line":"{friend:Agility}, extra bedrolls rolled tight by the fire while the square is quiet. Where is the rest of that watch tonight?"},"narratedSilence":null,"puzzle":{"q":"Are they keeping a blind vigil, or counting down to a known hour?","clickText":"Every stroke on the board—the crossed ones and the seven still to cross—was drawn from the start in the same square hand, and at dusk every head lifts together with the beat. The count was fixed before the watch began, and the hall beneath them is keeping the same time."},"clicks":[{"a":"5-5-1","b":"5-5-2","text":"Every stroke on the board—the crossed ones and the seven still to cross—was drawn from the start in the same square hand, and at dusk every head lifts together with the beat. The count was fixed before the watch began, and the hall beneath them is keeping the same time.","solves":true}],"riddle":null,"leads":[{"id":"5-5-1","place":"the board propped by the wall","actions":[{"attr":"Aim","verb":"read the board from the rubble"},{"attr":"Agility","verb":"creep close enough to see the chalk"}],"clueTitle":"One hand","clueText":"Every stroke on the board is in the same thick, square hand, the crossed ones and the ones still to cross. The chalk has been gone over many times, never redrawn.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-2","place":"the hooded figures at the fire","actions":[{"attr":"Aim","verb":"watch their faces from the rubble"},{"attr":"Agility","verb":"crawl close enough to see them"}],"clueTitle":"Every head lifts","clueText":"Every one of them sits facing the doors. When the beat comes, every head lifts at once, and stays lifted until it has passed.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-3","place":"the shell of the house across the square","actions":[{"attr":"Agility","verb":"slip round to its back wall"},{"attr":"Aim","verb":"look in through the broken window"}],"clueTitle":"More bedrolls","clueText":"Round the fire lie more bedrolls than there are people at it, each one rolled tight and tied.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Where we could watch it, and watch him.\"* Were they watching to keep him in, or waiting for the night the seal would fail?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay in the rubble until full dark, and keep your watches there by turns, with the Order''s fire showing red through the gaps all night.\n\n**Counting down to what? You hold five pieces, and the trail began on the wall. The wall again.**"}'::jsonb),
('dark-moon', 1, 5, 6, '{"place":"The wall again","narrated":false,"tone":"wry","cupNight":false,"opener":"A slit window, a hidden room, a night nobody heard you.","questionTitle":"The fifth Stone lies inside the wall beneath our feet, and we carry the mark in our blood. What happens when we open that room tonight?","forkA":"Our blood will wake the fifth right here in the wall and end his waking.","forkB":"Finding the fifth here is only half the task — it will have to be taken to his hall.","callback":"Every map before tonight was read out loud. Tonight it went hand to hand, and nobody heard.","nudge":"{friend:Aim}, two shallow dips worn into the parapet where elbows rested, facing straight up at the hall.","nudgeIfLaid":{"piece":"5-6-2","line":"{friend:Craft}, two shallow dips worn into the stone parapet where elbows rested for years, facing the hall. Someone stood guard over this hidden room until the end."},"narratedSilence":null,"puzzle":{"q":"How did the room stay hidden from the Order for centuries?","clickText":"The walkway here was built a full stride wider on the city side, and the slit window is set so low in the stone face that it cannot be seen from the square. Anyone not standing on this parapet would take the wall for solid rock."},"clicks":[{"a":"5-6-1","b":"5-6-3","text":"The walkway here was built a full stride wider on the city side, and the slit window is set so low in the stone face that it cannot be seen from the square. Anyone not standing on this parapet would take the wall for solid rock.","solves":true}],"riddle":null,"leads":[{"id":"5-6-1","place":"the city side of the wall, below the walk","actions":[{"attr":"Aim","verb":"lean out over the parapet"},{"attr":"Might","verb":"brace on the parapet and lean far out"}],"clueTitle":"The narrow slit","clueText":"The slit is no wider than a hand, low in the wall''s face. Unless you lean out over the parapet and look straight down the stone, you cannot see it at all.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-2","place":"the parapet on the city side","actions":[{"attr":"Craft","verb":"run a hand along the parapet''s top"},{"attr":"Might","verb":"lean your weight where others leaned"}],"clueTitle":"Two shallow dips","clueText":"Above where the map points, the parapet''s top is worn into two shallow dips, the width of a pair of elbows. They face the hall.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-3","place":"the forty paces of open stone","actions":[{"attr":"Agility","verb":"pace the walk while their heads are turned"},{"attr":"Intellect","verb":"measure the walk against the gate-tower"}],"clueTitle":"A stride wider","clueText":"Here the walk is wider than at the gate, by a good stride. All of the extra width is on the city side.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"The five were joined.\"* Did joining the five Stones end the war, or only pause it?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The watch has changed. It is dark enough. Into the wall, tonight.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 6, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 6, 1, '{"place":"The wall room (Six nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Quiet''s good in a hole in a wall. I''ll take it.","questionTitle":"The searchers walked past our door twice and found nothing, yet the watchman at the board still looked down at the wall at dusk. Why?","forkA":"He still believes someone is hiding in the wall; the Order has not given up the search.","forkB":"He is only checking that the rampart stays dark before he strikes the night''s chalk.","callback":"At dusk you crossed the wall and nobody heard. By the end of the night a watchman was looking straight at your window.","nudge":"{friend:Aim}, he paused with the chalk in his hand and looked down the hill at the wall before he struck the board. Was he hunting a light, or keeping a routine?","nudgeIfLaid":{"piece":"6-1-2","line":"{friend:Aim}, he stopped with the chalk in his hand and looked straight down at the wall before he struck the board. Was he looking for us, or checking his post?"},"narratedSilence":null,"puzzle":{"q":"What was kept in the stone niche before you opened the room?","clickText":"Years of candle-soot blacken the back of the niche facing the inner wall, while tonight no lantern from the square reaches through the slit. For generations a hidden light burned behind the Stone in this room; tonight the niche is cold and the Stone is in your hands."},"clicks":[{"a":"6-1-1","b":"6-1-3","text":"Years of candle-soot blacken the back of the niche facing the inner wall, while tonight no lantern from the square reaches through the slit. For generations a hidden light burned behind the Stone in this room; tonight the niche is cold and the Stone is in your hands.","solves":true}],"riddle":null,"leads":[{"id":"6-1-1","place":"the slit, after dark","actions":[{"attr":"Aim","verb":"watch the lanterns from the slit"},{"attr":"Intellect","verb":"follow where each lantern goes"}],"clueTitle":"No light inside","clueText":"Not a candle burns in the room. Every lantern you can see from the slit is out in the square, and none of them reaches in.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-2","place":"the board in the square","actions":[{"attr":"Aim","verb":"watch the board from the slit at dusk"},{"attr":"Intellect","verb":"watch the man with the chalk, not the board"}],"clueTitle":"One look down the hill","clueText":"At dusk the watchman with the chalk stops before he strikes the board. He turns, looks down the hill at the wall, and then strikes it.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-3","place":"the stone niche where it lay","actions":[{"attr":"Craft","verb":"hold a hand inside and feel the stone"},{"attr":"Intellect","verb":"look at the niche with the lamp unlit"}],"clueTitle":"The old soot","clueText":"The back of the stone niche is blackened in one small round patch, the way a candle marks stone over years. The niche faces the inner wall, away from the slit.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We let them go.\"* Was sparing those who still loved him mercy, or the mistake that brought us here?","weekQuestion":"What will the fifth do in his hall?","pull":"**The hall is sealed, and the Seekers left a way in, somewhere. The arrow points down: the defenders'' barracks, under the wall.**"}'::jsonb),
('dark-moon', 1, 6, 2, '{"place":"The barracks under the wall (Five nights)","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"When the ceiling came down, a hollowed soldier stood in our doorway, looked at the fallen stone, and walked on toward the hall at the heartbeat. What is moving the dead garrison across Highwall?","forkA":"The waking heart inside the hall is drawing every soldier back to the place where he fell.","forkB":"They are still carrying out their last order from the night the barracks emptied: form ranks at the hall.","callback":"Last week you couldn''t be sure a helm had turned toward you. Today one stood in your doorway and looked at the fallen stone instead.","nudge":"{friend:Agility}, empty spear-racks swept clean, bowls never filled, and every iron boot in the city stepping once when the beat comes.","nudgeIfLaid":{"piece":"6-2-3","line":"{friend:Craft}, bowls set out along the kitchen board and a ladle in the cold pot, never filled. Whatever called that garrison out of the barracks didn''t let them finish supper."},"narratedSilence":"Garrick rests his head against the cold masonry, listening to the hollow thud of the earth below in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"6-2-1","place":"where the spears once stood","actions":[{"attr":"Craft","verb":"look at the dust under the racks"},{"attr":"Intellect","verb":"walk the racks end to end"}],"clueTitle":"The swept racks","clueText":"The spear-racks along the wall are empty, and the dust under every one is swept clean in the same short arc.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-2","place":"the stair up to the street","actions":[{"attr":"Agility","verb":"climb to the top step and listen"},{"attr":"Intellect","verb":"count what you hear"}],"clueTitle":"Every foot at once","clueText":"When the heartbeat comes, you hear iron move all over the city at once: one scrape of a foot from every street, then quiet.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-3","place":"the kitchen whose fire went out","actions":[{"attr":"Craft","verb":"look over the board and the pot"},{"attr":"Might","verb":"lift the lid of the cold pot"}],"clueTitle":"Bowls never filled","clueText":"In the kitchen, bowls are set out along the board for a meal, and a ladle lies in the cold pot. Not one bowl was filled.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"That is how we found the shards.\"* Why did the shards answer to the five before anyone else?","weekQuestion":"What will the fifth do in his hall?","pull":"**They are not coming for you. They are going to him. And wherever the Seekers'' way in begins, it begins at his walls. The great square, after dark.**"}'::jsonb),
('dark-moon', 1, 6, 3, '{"place":"The great square (Four nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"The hall''s warm from within. More faithful arriving. What''s missing is a door.","questionTitle":"The hall''s stone wall is warm from the floor up behind sealed bronze doors, while new arrivals stack clean robes by their fire outside. Has the Order already set the four Stones inside, or are they still waiting outside for the last night?","forkA":"The four Stones are already set around him on the floor inside, warming the stone.","forkB":"The Stones are still outside with the faithful, waiting to be carried in on the dark moon.","callback":"The soldiers are three streets nearer the hall. Round the Order''s fire there are twice as many as before.","nudge":"{friend:Intellect}, clean robes folded on top of their road-packs outside, and warmth in the stone wall only from knee-height down.","nudgeIfLaid":{"piece":"6-3-2","line":"{friend:Aim}, road-packs still unrolled by their fire, with clean robes folded on top of every one. They didn''t ride here for a fight—they came dressed for a ceremony."},"narratedSilence":null,"puzzle":{"q":"Where is the heat in the hall''s wall coming from?","clickText":"An unbroken bank of dust lies across the seam of the bronze doors, and the stone wall is warm only from knee-height down. The front doors have never opened, and whatever is warming the hall lies flat on the floor inside."},"clicks":[{"a":"6-3-1","b":"6-3-3","text":"An unbroken bank of dust lies across the seam of the bronze doors, and the stone wall is warm only from knee-height down. The front doors have never opened, and whatever is warming the hall lies flat on the floor inside.","solves":true}],"riddle":null,"leads":[{"id":"6-3-1","place":"the foot of the great doors","actions":[{"attr":"Agility","verb":"slip along the wall to the doors"},{"attr":"Craft","verb":"look at the ground under the seam"}],"clueTitle":"The unbroken drift","clueText":"At the foot of the great doors, dust has drifted against the seam in one smooth bank, from post to post. Nothing has crossed it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-2","place":"the ruined house across from the hall","actions":[{"attr":"Aim","verb":"pick out what is stacked by their fire"},{"attr":"Agility","verb":"creep along the ruined house''s wall"}],"clueTitle":"Clean robes","clueText":"By the Order''s fire the new men''s packs are stacked in a row. On top of each lies a folded robe, brushed clean of the road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-3","place":"the hall''s great wall","actions":[{"attr":"Craft","verb":"feel the stone, hand over hand"},{"attr":"Might","verb":"climb a little way and feel higher"}],"clueTitle":"Warm low down","clueText":"Move your palm up the wall and the stone cools. The warmth is only low down, at the height of your knee and below.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"None of us could bear to lift him.\"* Even at the end, why could they not bring themselves to touch him?","weekQuestion":"What will the fifth do in his hall?","pull":"You cross back on the change of the watch, while the two men are looking at each other, and sleep in the wall room with the warmth of that stone still in your palm.\n\n**He is on the other side of this wall. Inside, on the night the moon goes dark, with the fifth: that is the whole plan now. The cracked hill behind the hall.**"}'::jsonb),
('dark-moon', 1, 6, 4, '{"place":"The hill behind the hall (Three nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"That hill was steeper than it looked. Sit.","questionTitle":"Every other soldier in Highwall faces the hall. Why has this one stood in the mouth of the Seekers'' crack since the war ended, facing out?","forkA":"The Seekers left it to bar their own secret passage after they sealed the hall and walked out.","forkB":"It was keeping the king''s last watch — guarding the back of his throne against anyone coming down the hill.","callback":"Upriver, a dog on a chain kept the hidden path. Today a soldier stood in the crack with its back to the hall.","nudge":"{friend:Craft}, two hollows worn into solid stone by iron boots, and the heartbeat louder right behind the blank rock than anywhere else.","nudgeIfLaid":{"piece":"6-4-3","line":"{friend:Charm}, put your ear to that blank rock and the heartbeat is louder than anywhere in the crack. The throne is right on the other side of that stone."},"narratedSilence":null,"puzzle":{"q":"How long had the sentinel stood in the mouth of the crack?","clickText":"The grit behind the soldier lay smooth and untouched until your boots marked it, while the rock under its iron soles is worn into two shallow hollows. Nobody has passed down this crack since the war ended, and that soldier never left its post."},"clicks":[{"a":"6-4-1","b":"6-4-2","text":"The grit behind the soldier lay smooth and untouched until your boots marked it, while the rock under its iron soles is worn into two shallow hollows. Nobody has passed down this crack since the war ended, and that soldier never left its post.","solves":true}],"riddle":null,"leads":[{"id":"6-4-1","place":"inside the crack, by lamplight","actions":[{"attr":"Agility","verb":"go in sideways, lamp first"},{"attr":"Aim","verb":"light the ground ahead and look"}],"clueTitle":"The untouched grit","clueText":"Past where the soldier stood, the grit on the crack''s floor lies smooth and untouched. Your boots are the first marks in it.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-2","place":"the soldier in the mouth of the crack","actions":[{"attr":"Might","verb":"drag the broken armour aside"},{"attr":"Craft","verb":"look at the rock it stood on"}],"clueTitle":"Two hollows","clueText":"The rock where it stood is worn into two shallow hollows, one for each foot. It stood on that one spot, facing out, for a very long time.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-3","place":"the blank rock at the dead end","actions":[{"attr":"Agility","verb":"squeeze on to the very end"},{"attr":"Charm","verb":"keep everyone quiet, and listen"}],"clueTitle":"Louder here","clueText":"Put your ear to the blank rock. When the heartbeat comes, it is louder here than anywhere else in the crack.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Forgive us for leaving it at all.\"* Why leave a way back into a room they hoped would stay shut forever?","weekQuestion":"What will the fifth do in his hall?","pull":"**What does a full moon struck dark mean? The moon-tower.**"}'::jsonb),
('dark-moon', 1, 6, 5, '{"place":"The moon-tower (Two nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Two nights. Eat while there''s something to eat.","questionTitle":"The sky-watchers'' wall stops on the dark moon the night he fell, with a Seeker housing set beside the last cut. Who were the sky-watchers reckoning that cycle for?","forkA":"For the Seekers: they marked the cycle so their descendants could count the blank wall and know the hour.","forkB":"For the king: they were his own watchers, reckoning the return of the dark moon before the city fell.","callback":"The Order''s board has counted down for generations. The sky-watchers'' wall, counted forward, lands on the same night.","nudge":"{friend:Intellect}, every row spaced a finger''s width apart for generations, and slates on the floor scratched with long sums begun again.","nudgeIfLaid":{"piece":"6-5-1","line":"{friend:Intellect}, every moon spaced a finger''s width from the last around the whole room. Measure the blank wall by that same thumb, and it counts straight to tomorrow night."},"narratedSilence":null,"puzzle":{"q":"What were the sky-watchers doing in the days before the wall went blank?","clickText":"The last rows of moons were chiselled in a rough hurry without missing a single night, while the slates on the floor are covered in long sums crossed through and begun again. They were racing to reckon a distant date before the last night came."},"clicks":[{"a":"6-5-2","b":"6-5-3","text":"The last rows of moons were chiselled in a rough hurry without missing a single night, while the slates on the floor are covered in long sums crossed through and begun again. They were racing to reckon a distant date before the last night came.","solves":true}],"riddle":null,"leads":[{"id":"6-5-1","place":"the sky-watchers'' wall, row by row","actions":[{"attr":"Intellect","verb":"measure the space between the moons"},{"attr":"Aim","verb":"follow one row all the way round"}],"clueTitle":"A finger''s width","clueText":"Lay a finger between any two moons, on any row. The space is the same every time, year on year, round the whole room.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-2","place":"the floor of the round room","actions":[{"attr":"Craft","verb":"gather up what lies on the floor"},{"attr":"Intellect","verb":"read the scratches by daylight"}],"clueTitle":"Sums begun again","clueText":"On the floor lie the sky-watchers'' slates, scratched with long sums. Many are crossed through and begun again.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-3","place":"where the rows stop","actions":[{"attr":"Might","verb":"climb the ledges to the last rows"},{"attr":"Craft","verb":"run a thumb along the last cuts"}],"clueTitle":"Cut in a hurry","clueText":"In the last rows before they stop, every moon is cut to the right depth, but the edges are rough, as if made in a hurry. Not one night is missing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Be there when it does.\"* Did the Seekers trust their descendants to hold the lock, or to end it?","weekQuestion":"What will the fifth do in his hall?","pull":"**You have the hour. One piece is left, and the Seekers'' way ends at a blank rock with this same moon beside it. Tomorrow is the last day.**"}'::jsonb),
('dark-moon', 1, 6, 6, '{"place":"The crack in the hill (One night)","narrated":false,"tone":"wry","cupNight":true,"opener":"Last night of the count. Eat what you like.","questionTitle":"Tomorrow night the Seekers'' door opens for our blood, and we carry the fifth Stone into the hall where the four are waiting. What happens when the fifth is brought to him?","forkA":"It finishes what the Seekers built their hidden door for — binding him before the four Stones can wake him.","forkB":"It finishes what the four Stones and the marching garrison are waiting for — waking him whole.","callback":"Six nights ago you had a hidden room. Tonight you have one stroke left.","nudge":"{friend:Intellect}, grit swept in a quarter-circle where the stone door swings inward, and every helm on the hill turned toward the hall.","nudgeIfLaid":{"piece":"6-6-3","line":"{friend:Agility}, every post from the gate-tower to the crossroads stands empty tonight, with only pale boot-marks in the dust. Nothing is left behind us."},"narratedSilence":null,"puzzle":{"q":"Will the dead garrison see you when the blank rock opens?","clickText":"At the foot of the blank rock the grit is swept in a quarter-circle where a hidden door swings toward you, and outside the crack every helm on the hill is turned toward the hall''s great doors. When the Seekers'' door opens tomorrow night, the entire garrison will have its back to you."},"clicks":[{"a":"6-6-1","b":"6-6-2","text":"At the foot of the blank rock the grit is swept in a quarter-circle where a hidden door swings toward you, and outside the crack every helm on the hill is turned toward the hall''s great doors. When the Seekers'' door opens tomorrow night, the entire garrison will have its back to you.","solves":true}],"riddle":null,"leads":[{"id":"6-6-1","place":"the street below the crack","actions":[{"attr":"Aim","verb":"watch the street from the crack''s mouth"},{"attr":"Intellect","verb":"count the ranks as they climb"}],"clueTitle":"Every helm to the hall","clueText":"From the crack''s mouth you can see the whole street climbing toward you. Every helm in it is turned to the hall, not one to the hill.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-2","place":"the foot of the blank rock","actions":[{"attr":"Craft","verb":"look at how the grit lies"},{"attr":"Agility","verb":"get down low with the lamp"}],"clueTitle":"The swept fan","clueText":"At the foot of the blank rock, the old grit on your side lies swept flat in a smooth quarter-circle. Its point is at the rock''s left edge.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-3","place":"the streets you crossed this morning","actions":[{"attr":"Aim","verb":"look back down the hill from the crack"},{"attr":"Agility","verb":"go back the long way, street by street"}],"clueTitle":"Every post empty","clueText":"The crossroads, the gate-tower, the street under the wall: every place where a soldier stood is empty now. Only the pale marks of their boots are left.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Finish what we could not.\"* What could five who loved him not bring themselves to do?","weekQuestion":"What will the fifth do in his hall?","pull":"**Tomorrow night, when the moon goes dark: through the Seekers'' door, into his hall, with the fifth in your hands.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- Ensure fire_check_clicks matches both bare lead IDs ("1-2-2") and prefixed piece keys ("lead:1-2-2")
create or replace function public.fire_check_clicks(p_party uuid, p_week int, p_day int) returns void
language plpgsql security definer set search_path = '' as $$
declare v_data jsonb := public.campfire_data(p_party, p_week, p_day); v_pieces jsonb; c jsonb; i int := 0;
        v_a jsonb; v_b jsonb; v_names text[]; v_ua text; v_ub text;
begin
  if jsonb_typeof(v_data -> 'clicks') <> 'array' or coalesce((v_data ->> 'narrated')::boolean, false) then return; end if;
  v_pieces := public.fire_pieces(p_party, p_week, p_day);
  for c in select * from jsonb_array_elements(v_data -> 'clicks') loop
    i := i + 1;
    continue when exists (select 1 from public.fire_clicks where party_id = p_party and week = p_week and day = p_day and idx = i);
    select p into v_a from jsonb_array_elements(v_pieces) p
    where p ->> 'key' in (c ->> 'a', 'lead:' || (c ->> 'a'))
       or (c ->> 'a' = 'notice' and p ->> 'kind' = 'notice' and p ->> 'attr' = c ->> 'aAttr');
    select p into v_b from jsonb_array_elements(v_pieces) p
    where p ->> 'key' in (c ->> 'b', 'lead:' || (c ->> 'b'));
    continue when v_a is null or v_b is null;
    select b1 ->> 'name', b2 ->> 'name' into v_ua, v_ub
    from jsonb_array_elements(v_a -> 'by') b1, jsonb_array_elements(v_b -> 'by') b2
    where b1 ->> 'id' <> b2 ->> 'id' limit 1;
    continue when v_ua is null;
    v_names := array[v_ua, v_ub];
    insert into public.fire_clicks (party_id, week, day, idx, names) values (p_party, p_week, p_day, i, v_names)
    on conflict do nothing;
    if found then
      insert into public.fire_thread (party_id, week, day, kind, body) values (p_party, p_week, p_day, 'click', c ->> 'text');
    end if;
  end loop;
end;
$$;

-- Helper for read-backs across Weeks 1-6 (supports solo first-person and multi-friend calls without grading)
create or replace function public.fire_read_back_line(
  p_party uuid,
  p_week int,
  p_day int,
  p_solo_prefix text,
  p_party_prefix text,
  p_default text default 'A'
) returns text
language plpgsql stable security definer set search_path = '' as $$
declare
  v_call jsonb := public.fire_call(p_party, p_week, p_day);
  v_data jsonb := public.campfire_data(p_party, p_week, p_day);
  v_members int;
  v_my_reading text;
  v_fork text;
begin
  select count(*) into v_members from public.party_members where party_id = p_party;
  if v_members <= 1 or (p_week = 1 and p_day = 1) then
    select reading into v_my_reading from public.fire_pins
    where party_id = p_party and user_id = auth.uid() and week = p_week and day = p_day;
    v_fork := case coalesce(v_my_reading, p_default)
      when 'A' then v_data ->> 'forkA'
      else v_data ->> 'forkB'
    end;
    return p_solo_prefix || ': ' || coalesce(v_fork, '');
  end if;

  if v_call ->> 'reading' = 'A' then
    return p_party_prefix || ': ' || coalesce(v_data ->> 'forkA', '');
  elsif v_call ->> 'reading' = 'B' then
    return p_party_prefix || ': ' || coalesce(v_data ->> 'forkB', '');
  elsif coalesce((v_call ->> 'split')::boolean, false) then
    return 'The fire was split on Day ' || p_day || '.';
  else
    v_fork := case p_default when 'A' then v_data ->> 'forkA' else v_data ->> 'forkB' end;
    return p_party_prefix || ': ' || coalesce(v_fork, '');
  end if;
end;
$$;

-- Weekday read-backs across Weeks 1-6
create or replace function public.party_read_backs(p_party uuid, p_week int, p_day int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_out jsonb := '[]'::jsonb;
begin
  if p_week = 1 and p_day = 2 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'So the list is hers.',
      'day', 1,
      'text', public.fire_read_back_line(p_party, 1, 1, 'Last night you called it', 'Last night you called it', 'B')
    ));
  elsif p_week = 1 and p_day = 4 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'He has half a day on you',
      'day', 3,
      'text', public.fire_read_back_line(p_party, 1, 3, 'On Day 3 you called it', 'The fire''s call on Day 3', 'B')
    ));
  elsif p_week = 1 and p_day = 5 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'About the last one.',
      'day', 2,
      'text', public.fire_read_back_line(p_party, 1, 2, 'On Day 2 you called it', 'The fire''s call on Day 2', 'B')
    ));
  elsif p_week = 2 and p_day = 2 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'knew the night he was born',
      'day', 1,
      'text', public.fire_read_back_line(p_party, 2, 1, 'Last night you called it', 'The fire''s call on Day 1', 'B')
    ));
  elsif p_week = 3 and p_day = 2 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'passed within a mile of her own door.',
      'day', 1,
      'text', public.fire_read_back_line(p_party, 3, 1, 'Last night you called it', 'The fire''s call on Day 1', 'B')
    ));
  elsif p_week = 4 and p_day = 6 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'there is nobody in it',
      'day', 5,
      'text', public.fire_read_back_line(p_party, 4, 5, 'Last night you called it', 'The fire''s call on Day 5', 'A')
    ));
  elsif p_week = 5 and p_day = 5 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'They have made their camp facing the doors',
      'day', 3,
      'text', public.fire_read_back_line(p_party, 5, 3, 'On Day 3 you called it', 'The fire''s call on Day 3', 'A')
    ));
  elsif p_week = 6 and p_day = 3 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'there are twice as many round it as there were.',
      'day', 1,
      'text', public.fire_read_back_line(p_party, 6, 1, 'On Day 1 you called it', 'The fire''s call on Day 1', 'B')
    ));
  elsif p_week = 6 and p_day = 6 then
    v_out := jsonb_build_array(jsonb_build_object(
      'anchor', 'At the mouth of the crack, one soldier has stopped walking, and turned round.',
      'day', 4,
      'text', public.fire_read_back_line(p_party, 6, 4, 'On Day 4 you called it', 'The fire''s call on Day 4', 'B')
    ));
  end if;
  return v_out;
end;
$$;

-- Gathering read-backs across Gatherings 1-6
create or replace function public.gathering_read_backs(p_party uuid, p_week int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_out jsonb := '[]'::jsonb;
begin
  if p_week = 1 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'The first is Tamsin''s.', 'day', 4,
        'text', public.fire_read_back_line(p_party, 1, 4, 'On Day 4 you called it', 'The fire called it on Day 4', 'A')),
      jsonb_build_object('anchor', 'Whoever tied them has tied a great many.', 'day', 5,
        'text', public.fire_read_back_line(p_party, 1, 5, 'On Day 5 you called it', 'The fire called it on Day 5', 'B')),
      jsonb_build_object('anchor', 'None of them is yours.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 1, 6, 'Your case, after Week 1', 'The fire''s case, after Week 1', 'B'))
    );
  elsif p_week = 2 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'have done this many times before.', 'day', 4,
        'text', public.fire_read_back_line(p_party, 2, 4, 'On Day 4 you called it', 'The fire called it on Day 4', 'B')),
      jsonb_build_object('anchor', 'Whatever sat here left recently, not centuries ago.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 2, 6, 'Last night you called it', 'The fire called it on Day 6', 'A')),
      jsonb_build_object('anchor', 'scraped it from its stones', 'day', 5,
        'text', public.fire_read_back_line(p_party, 2, 5, 'On Day 5 you called it', 'The fire called it on Day 5', 'A')),
      jsonb_build_object('anchor', 'Beside each place, a date', 'day', 2,
        'text', public.fire_read_back_line(p_party, 2, 2, 'On Day 2 you called it', 'The fire called it on Day 2', 'A')),
      jsonb_build_object('anchor', 'Every one of you.', 'day', 3,
        'text', public.fire_read_back_line(p_party, 2, 3, 'On Day 3 you called it', 'The fire called it on Day 3', 'B'))
    );
  elsif p_week = 3 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'They are waiting for you.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 3, 6, 'Last night you called it', 'The fire called it on Day 6', 'A')),
      jsonb_build_object('anchor', 'puts the eight from the ridges into her other hand', 'day', 4,
        'text', public.fire_read_back_line(p_party, 3, 4, 'On Day 4 you called it', 'The fire called it on Day 4', 'A')),
      jsonb_build_object('anchor', 'every sealed thing of theirs has opened for you', 'day', 3,
        'text', public.fire_read_back_line(p_party, 3, 3, 'On Day 3 you called it', 'The fire called it on Day 3', 'A')),
      jsonb_build_object('anchor', 'Therefore the faithful shall not lie.', 'day', 2,
        'text', public.fire_read_back_line(p_party, 3, 2, 'On Day 2 you called it', 'The fire called it on Day 2', 'A')),
      jsonb_build_object('anchor', 'Until the throne rise whole.', 'day', 5,
        'text', public.fire_read_back_line(p_party, 3, 5, 'On Day 5 you called it', 'The fire called it on Day 5', 'B'))
    );
  elsif p_week = 4 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'Those still on their feet do not stand, as they stood under the Kiln.', 'day', 1,
        'text', public.fire_read_back_line(p_party, 4, 1, 'On Day 1 you called it', 'The fire called it on Day 1', 'B')),
      jsonb_build_object('anchor', 'We have waited for those who can open them.', 'day', 3,
        'text', public.fire_read_back_line(p_party, 4, 3, 'On Day 3 you called it', 'The fire called it on Day 3', 'B')),
      jsonb_build_object('anchor', 'four armed riders, and one closed box between them', 'day', 2,
        'text', public.fire_read_back_line(p_party, 4, 2, 'On Day 2 you called it', 'The fire called it on Day 2', 'A')),
      jsonb_build_object('anchor', 'Where the Seekers'' children walk, the faithful follow.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 4, 6, 'Last night you called it', 'The fire called it on Day 6', 'A')),
      jsonb_build_object('anchor', 'The fifth heeds no element at all', 'day', 4,
        'text', public.fire_read_back_line(p_party, 4, 4, 'On Day 4 you called it', 'The fire called it on Day 4', 'B'))
    );
  elsif p_week = 5 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'They kept it near him, under their own eyes.', 'day', 1,
        'text', public.fire_read_back_line(p_party, 5, 1, 'On Day 1 you called it', 'The fire called it on Day 1', 'A')),
      jsonb_build_object('anchor', 'Tonight they were moving.', 'day', 4,
        'text', public.fire_read_back_line(p_party, 5, 4, 'On Day 4 you called it', 'The fire called it on Day 4', 'B')),
      jsonb_build_object('anchor', 'your blood runs off it like rain off glass.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 5, 6, 'Last night you called it', 'The fire called it on Day 6', 'B')),
      jsonb_build_object('anchor', 'The sleep is thinnest when the moon goes dark.', 'day', 5,
        'text', public.fire_read_back_line(p_party, 5, 5, 'On Day 5 you called it', 'The fire called it on Day 5', 'A'))
    );
  elsif p_week = 6 then
    v_out := jsonb_build_array(
      jsonb_build_object('anchor', 'At its edge, a sliver of it has already gone dark, and the dark is spreading.', 'day', 5,
        'text', public.fire_read_back_line(p_party, 6, 5, 'On Day 5 you called it', 'The fire called it on Day 5', 'A')),
      jsonb_build_object('anchor', 'his soldiers from the last war, still standing their watch after all these centuries.', 'day', 2,
        'text', public.fire_read_back_line(p_party, 6, 2, 'On Day 2 you called it', 'The fire called it on Day 2', 'A')),
      jsonb_build_object('anchor', 'Around him, set in a ring, faintly glowing, are the four Stones.', 'day', 3,
        'text', public.fire_read_back_line(p_party, 6, 3, 'On Day 3 you called it', 'The fire called it on Day 3', 'A')),
      jsonb_build_object('anchor', 'What the four begin, the fifth shall end', 'day', 2,
        'text', public.fire_read_back_line(p_party, 5, 2, 'In Week 5 you called it', 'The fire''s call in Week 5', 'A')),
      jsonb_build_object('anchor', 'Same key. Turned the other way.', 'day', 6,
        'text', public.fire_read_back_line(p_party, 6, 6, 'Last night you called it', 'The fire called it on Day 6', 'B'))
    );
  end if;
  return v_out;
end;
$$;
